/* KHBD Mĩ thuật Lớp 2 KNTT — Bút Xanh, tích hợp NLS+AI */
window.KHO_DATA_L2_MITHUAT = [
{"lop":2,"mon":"Mĩ thuật","tuan":1,"tiet":1,"bai":"Chủ đề 1: MĨ THUẬT TRONG CUỘC SỐNG","yccd":"1. Năng lực mĩ thuật\n- Nhận biết được hình thức và sự xuất hiện đa dạng của mĩ thuật trong cuộc sống.\n- Gọi được tên một số hình thức biểu hiện của mĩ thuật ở xung quanh (pa-nô, áp phích, sản phẩm thủ công, đồ lưu niệm...).\n- Nhận ra sự phong phú của mĩ thuật trong cuộc sống.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động quan sát tranh, ảnh, đồ vật xung quanh và kể lại những gì đã thấy.\n- Giao tiếp và hợp tác: mạnh dạn chia sẻ hiểu biết của mình trước lớp, lắng nghe ý kiến của bạn.\n3. Phẩm chất\n- Yêu thích một số hình thức biểu hiện của mĩ thuật trong cuộc sống xung quanh.\n- Có ý thức giữ gìn cảnh quan, sự vật, đồ vật có tính mĩ thuật.\n4. Tích hợp\n- Năng lực số 1.1 CB1 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS gọi tên được các hình thức mĩ thuật trong cuộc sống qua bộ ảnh.","dodung":"- Giáo viên: một số tác phẩm, sản phẩm mĩ thuật gần gũi ở địa phương; tranh ảnh, clip (nếu có điều kiện) về sự xuất hiện của mĩ thuật trong cuộc sống; thiết bị trình chiếu học liệu số.\n- Học sinh: SGK Mĩ thuật 2, Vở bài tập Mĩ thuật 2, bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS chơi trò chơi Tranh và tượng: chia hai nhóm, xem hình ảnh và tìm nhanh đâu là tranh, đâu là tượng.\n- GV nêu luật chơi, nhận xét, tuyên dương và dẫn vào chủ đề.","hs":"- HS tham gia trò chơi theo nhóm, quan sát và xác định tranh, tượng.\n- HS lắng nghe, mở bài học."},{"ten":"2. Khám phá — Mĩ thuật quanh em","gv":"- GV mời HS nêu hiểu biết của mình về các tác phẩm, sản phẩm mĩ thuật đã biết.\n- GV cho HS quan sát hình trang 5-7 SGK Mĩ thuật 2, đặt câu hỏi: Đây là tác phẩm, sản phẩm gì? Thường thấy ở đâu?\n- GV bổ sung, làm rõ các hình thức mĩ thuật: pa-nô, áp phích ngày lễ; cờ trang trí ngày khai giảng; sản phẩm thủ công, đồ lưu niệm, sản phẩm từ vật liệu tái sử dụng.","hs":"- HS nêu hiểu biết của mình.\n- HS quan sát hình, trả lời câu hỏi.\n- HS lắng nghe, ghi nhớ về các hình thức mĩ thuật trong cuộc sống."},{"ten":"3. Luyện tập — Kể và giới thiệu","gv":"- GV mời từng HS nói về tác phẩm, sản phẩm mĩ thuật đã nhìn thấy ở trường, ở nhà hoặc nơi em đã đến.\n- GV ghi tóm tắt câu trả lời lên bảng (không đánh giá), khen ngợi, động viên HS.","hs":"- HS giới thiệu về những sản phẩm mĩ thuật mà mình đã thấy.\n- HS lắng nghe bạn chia sẻ."},{"ten":"4. Vận dụng","gv":"- GV yêu cầu HS nêu lại kiến thức bài học và liên hệ: em sẽ giữ gìn những đồ vật, cảnh quan đẹp như thế nào?\n- GV dặn HS về xem trước Chủ đề 2: Sự thú vị của nét.","hs":"- HS nêu lại kiến thức, chia sẻ ý thức giữ gìn cái đẹp.\n- HS ghi nhớ nhiệm vụ chuẩn bị."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV chiếu bộ ảnh về mĩ thuật quanh ta: pa-nô ngoài đường, bìa sách, bao bì bánh kẹo, hoa văn trên áo, tượng ở công viên; mỗi ảnh được phóng to một góc để HS thấy người ta đã chọn hình, chọn màu, chọn chữ cho từng thứ ra sao.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) HS chỉ trên màn hình thứ nào là tranh, thứ nào là đồ thủ công, thứ nào là công trình kiến trúc và nói mình đã gặp thứ đó ở đâu.\n⚠ (Miền 4: An toàn) GV mở đúng tập ảnh đã chuẩn bị trước, không mở trang mạng có quảng cáo chen ngang trong giờ học; xem ảnh xong HS ra hành lang tìm những thứ có trang trí ở ngay trong trường mình.","hs":"- HS gọi tên được các hình thức mĩ thuật trong cuộc sống qua bộ ảnh.\n- HS kể được nơi mình đã gặp sản phẩm mĩ thuật đó ngoài đời."}]},
{"lop":2,"mon":"Mĩ thuật","tuan":2,"tiet":2,"bai":"Chủ đề 2: SỰ THÚ VỊ CỦA NÉT — Tiết 1: Quan sát và thể hiện nét","yccd":"1. Năng lực mĩ thuật\n- Nhận ra được nét và các hình thức biểu hiện của nét trên sản phẩm mĩ thuật (nét cong, thẳng, gấp khúc...).\n- Nhận biết các chất liệu thực hiện sản phẩm mĩ thuật có sử dụng yếu tố nét.\n- Tạo được sản phẩm mĩ thuật làm nổi bật yếu tố nét bằng hình thức vẽ hoặc xé dán.\n2. Năng lực chung\n- Tự chủ và tự học: biết lựa chọn công cụ, chất liệu phù hợp để thực hành.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ cảm nhận về sản phẩm với bạn.\n3. Phẩm chất\n- Yêu thích sử dụng nét trong thực hành.\n- Có ý thức trao đổi, chia sẻ cảm nhận về sản phẩm mĩ thuật.\n4. Tích hợp\n- Năng lực số 1.1 CB1 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS nhận ra các loại nét có trong đồ vật quen thuộc qua ảnh phóng to.","dodung":"- Giáo viên: một số tranh, ảnh, đồ vật được trang trí bằng nét; sản phẩm mĩ thuật có nhiều loại nét khác nhau; thiết bị trình chiếu.\n- Học sinh: SGK Mĩ thuật 2, Vở bài tập Mĩ thuật 2, bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS chơi trò chơi Đoán tên của nét: GV vẽ nhanh các nét, nhóm nào gọi đúng tên nhiều nét hơn thì thắng.\n- GV nhận xét, tuyên dương và giới thiệu chủ đề.","hs":"- HS tham gia trò chơi, gọi tên các nét.\n- HS lắng nghe, mở bài học."},{"ten":"2. Khám phá — Quan sát nét","gv":"- GV cho HS quan sát hình trang 8-9 SGK Mĩ thuật 2 và một số đồ vật có nét trang trí.\n- GV đặt câu hỏi: Nét có ở đâu trên sản phẩm? Đó là những nét nào (cong, thẳng, gấp khúc)? Sản phẩm được tạo bằng chất liệu gì?\n- GV chốt: nét có nhiều trên sản phẩm mĩ thuật, tạo bằng nhiều cách và chất liệu khác nhau.","hs":"- HS quan sát, trả lời câu hỏi theo cảm nhận.\n- HS nhận biết các loại nét và chất liệu.\n- HS lắng nghe, ghi nhớ."},{"ten":"3. Luyện tập — Sáng tạo","gv":"- GV hướng dẫn HS tham khảo cách tạo nét trang 10 SGK Mĩ thuật 2 (vẽ hoặc xé, cắt dán giấy màu).\n- GV thị phạm trực tiếp và yêu cầu HS thực hành: dùng nét là chính để tạo một sản phẩm yêu thích.\n- GV quan sát, giúp đỡ HS hoàn thành, nhắc HS lưu giữ sản phẩm cho tiết sau.","hs":"- HS quan sát cách thị phạm, tiếp thu.\n- HS thực hành tạo sản phẩm làm nổi bật nét.\n- HS lưu giữ sản phẩm."},{"ten":"4. Vận dụng","gv":"- GV cho HS giới thiệu nhanh sản phẩm đang làm: em đã dùng những nét gì?\n- GV khen ngợi, động viên, dặn HS chuẩn bị tiếp cho tiết 2.","hs":"- HS chia sẻ về các nét trong sản phẩm.\n- HS ghi nhớ nhiệm vụ."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV chiếu ảnh chụp thật gần vân gỗ trên mặt bàn, đường chỉ trên tấm áo, sóng nước, mạng nhện; ảnh phóng to giúp HS nhận ra nét cong, nét thẳng, nét xoắn có sẵn trong đồ vật quanh mình mà nhìn lướt qua không thấy.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV dùng công cụ vẽ tô đè một đường lên ảnh để chỉ rõ đường nét muốn HS chú ý, tô xong lại xoá đi để chuyển sang ảnh khác.\n⚠ (Miền 4: An toàn) GV thao tác trên máy, HS ngồi tại chỗ quan sát; xem ảnh trên màn hình xong, HS sờ tay lên mặt bàn, lên tấm vải thật để cảm nhận nét bằng đầu ngón tay.","hs":"- HS nhận ra các loại nét có trong đồ vật quen thuộc qua ảnh phóng to.\n- HS chỉ ra được nét tương tự trên đồ vật thật trong lớp."}]},
{"lop":2,"mon":"Mĩ thuật","tuan":3,"tiet":3,"bai":"Chủ đề 2: SỰ THÚ VỊ CỦA NÉT — Tiết 2: Thảo luận và vận dụng","yccd":"1. Năng lực mĩ thuật\n- Củng cố kiến thức, kĩ năng liên quan đến yếu tố nét và cách tạo nét đã học.\n- Nhận biết được sự lặp lại của nét trong trang trí đường diềm.\n- Sử dụng nét màu để trang trí một đồ vật em yêu thích.\n2. Năng lực chung\n- Giao tiếp và hợp tác: trao đổi nhóm, trình bày cảm nhận về sản phẩm.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách trang trí phù hợp với đồ vật.\n3. Phẩm chất\n- Chăm chỉ hoàn thành sản phẩm; yêu thích cái đẹp trong trang trí đồ vật.\n4. Tích hợp\n- Năng lực số 3.2 CB1 (Tích hợp và tinh chỉnh nội dung số): HS nhận ra nhịp điệu của đường diềm sinh ra từ hoạ tiết lặp lại.","dodung":"- Giáo viên: sản phẩm mĩ thuật trang trí bằng nét; hình đường diềm mẫu; đồ vật để trang trí (đĩa nhựa, tấm thiệp, tấm bìa); thiết bị trình chiếu.\n- Học sinh: sản phẩm tiết 1, bút màu, giấy màu, kéo, hồ dán, đồ vật để trang trí.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV tổ chức trò chơi Chấm ở đâu, lồng ghép giải thích cách sắp xếp nét theo nguyên lí lặp lại.\n- GV nhận xét, tuyên dương, dẫn vào bài.","hs":"- HS tham gia trò chơi, lắng nghe.\n- HS mở bài học."},{"ten":"2. Khám phá — Thảo luận","gv":"- GV tổ chức cho HS trao đổi nhóm theo câu hỏi trang 11 SGK Mĩ thuật 2: Bài của bạn có những nét gì? Với những nét này có thể tạo hình gì khác? Em thích bài nào nhất?\n- GV gợi ý HS quan sát đường diềm để nhận biết sự lặp lại của hình con voi, bông hoa.\n- GV chỉ ra nguyên lí lặp lại, nhắc lại, nhịp điệu của nét.","hs":"- HS thảo luận nhóm, trả lời câu hỏi.\n- HS nhận biết sự lặp lại của nét trong đường diềm.\n- HS lắng nghe, ghi nhớ."},{"ten":"3. Luyện tập — Vận dụng","gv":"- GV cho HS quan sát cách dùng nét trang trí một chiếc đĩa (trang 12 SGK Mĩ thuật 2).\n- GV gợi ý HS trang trí một đĩa nhựa, tấm thiệp hoặc tấm bìa bằng nét màu.\n- GV quan sát, giúp đỡ HS hoàn thiện sản phẩm.","hs":"- HS quan sát, nhận biết cách thực hiện.\n- HS thực hành trang trí đồ vật bằng nét màu.\n- HS hoàn thiện sản phẩm."},{"ten":"4. Vận dụng — Trưng bày","gv":"- GV tổ chức cho HS trưng bày sản phẩm, chia sẻ: Bạn tạo được sản phẩm gì? Nét thể hiện ở đâu? Em thích sản phẩm nào nhất?\n- GV cùng HS nhận xét, động viên; dặn xem trước Chủ đề 3.","hs":"- HS trưng bày, giới thiệu sản phẩm.\n- HS nhận xét, ghi nhớ nhiệm vụ."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV mở một trang trình chiếu, vẽ một hoạ tiết rồi dùng lệnh sao chép và dán cho hoạ tiết ấy lặp lại thành đường diềm dài; HS thấy ngay nhịp điệu của trang trí sinh ra từ sự lặp lại đều đặn, GV đổi khoảng cách giữa các hoạ tiết thì đường diềm đổi theo.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) HS quan sát cạnh đó ảnh đường diềm trên khăn, trên bát đĩa để đối chiếu với đường diềm vừa dựng trên máy.\n⚠ (Miền 4: An toàn) GV thao tác sao chép, dán; HS quan sát và nêu ý kiến rồi tự vẽ đường diềm bằng tay trên giấy, vì chỉ vẽ tay mới rèn được nét đều.","hs":"- HS nhận ra nhịp điệu của đường diềm sinh ra từ hoạ tiết lặp lại.\n- HS chọn được khoảng cách lặp lại cho đường diềm của mình."}]},
{"lop":2,"mon":"Mĩ thuật","tuan":4,"tiet":4,"bai":"Chủ đề 3: SỰ KẾT HỢP CỦA CÁC HÌNH CƠ BẢN — Tiết 1: Quan sát và thể hiện (dạng 2D)","yccd":"1. Năng lực mĩ thuật\n- Nhận ra sự kết hợp của các hình cơ bản (tròn, vuông, chữ nhật, tam giác) để tạo nên hình dạng đồ vật, sự vật.\n- Củng cố kiến thức về hình cơ bản; nhận biết sự lặp lại của các hình.\n- Tạo được một vật có sự kết hợp của hình cơ bản dạng 2D bằng hình thức vẽ hoặc xé dán.\n2. Năng lực chung\n- Tự chủ và tự học: chọn nội dung, chất liệu phù hợp để thể hiện sản phẩm.\n- Giao tiếp và hợp tác: liên tưởng, chia sẻ ý tưởng với bạn.\n3. Phẩm chất\n- Yêu thích sử dụng các hình cơ bản trong thực hành; chăm chỉ, sáng tạo.\n4. Tích hợp\n- Năng lực số 1.1 CB1 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS chỉ ra được các hình cơ bản tạo nên một đồ vật khi xem hình tách và ghép.","dodung":"- Giáo viên: một số đồ vật có dạng kết hợp các hình cơ bản; hình cơ bản làm bằng dây thép, khối thạch cao (nếu có); hình ảnh, clip minh họa; thiết bị trình chiếu.\n- Học sinh: SGK Mĩ thuật 2, Vở bài tập Mĩ thuật 2, bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS chơi trò chơi Nhìn vật đoán hình: xem đồ vật và gọi tên các hình cơ bản tạo nên đồ vật đó.\n- GV nhận xét, tuyên dương, giới thiệu chủ đề.","hs":"- HS tham gia trò chơi, gọi tên hình cơ bản.\n- HS lắng nghe, mở bài học."},{"ten":"2. Khám phá — Quan sát sự kết hợp","gv":"- GV cho HS quan sát hình trang 13-15 SGK Mĩ thuật 2 và đồ vật thật.\n- GV đặt câu hỏi: Đồ vật này được kết hợp từ những hình cơ bản nào? (chữ nhật, vuông kết hợp tròn; kết hợp tam giác...).\n- GV gợi ý HS nhận ra sự lặp lại của hình cơ bản (đoàn tàu, đèn ông sao, chuồng chim...).","hs":"- HS quan sát, trả lời câu hỏi.\n- HS nhận biết sự kết hợp và lặp lại của các hình.\n- HS lắng nghe, ghi nhớ."},{"ten":"3. Luyện tập — Sáng tạo (2D)","gv":"- GV hướng dẫn HS tham khảo sản phẩm vẽ, xé dán ở trang 16 SGK Mĩ thuật 2.\n- GV yêu cầu HS thực hành vẽ hoặc xé dán một vật đơn giản có sự kết hợp của các hình cơ bản (dạng 2D) và trang trí theo ý thích.\n- GV quan sát, giúp đỡ; nhắc HS lưu giữ sản phẩm cho tiết sau.","hs":"- HS tham khảo, nhận biết cách làm.\n- HS thực hành tạo vật 2D từ các hình cơ bản.\n- HS lưu giữ sản phẩm."},{"ten":"4. Vận dụng","gv":"- GV mời HS chia sẻ: vật em làm được kết hợp từ những hình nào?\n- GV khen ngợi, dặn HS chuẩn bị cho tiết 2.","hs":"- HS chia sẻ về sản phẩm.\n- HS ghi nhớ nhiệm vụ."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV chiếu ảnh ngôi nhà, ô tô, tàu thuỷ rồi bấm cho từng hình cơ bản tách rời ra khỏi ảnh: mái nhà là hình tam giác, thân nhà là hình chữ nhật, bánh xe là hình tròn; tách rồi ghép lại vài lần để HS nhìn thấy cách một đồ vật được dựng nên từ các hình.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) HS chọn một đồ vật có trong lớp và kể ra đồ vật đó gồm những hình cơ bản nào.\n⚠ (Miền 4: An toàn) GV để máy chiếu ở độ sáng vừa phải và nhắc HS không nhìn thẳng vào bóng đèn máy chiếu; xem xong HS xếp hình bằng bìa cắt sẵn để tự tay ghép lại.","hs":"- HS chỉ ra được các hình cơ bản tạo nên một đồ vật khi xem hình tách và ghép.\n- HS kể được các hình cơ bản trong một đồ vật có thật ở lớp."}]},
{"lop":2,"mon":"Mĩ thuật","tuan":5,"tiet":5,"bai":"Chủ đề 3: SỰ KẾT HỢP CỦA CÁC HÌNH CƠ BẢN — Tiết 2: Thể hiện (dạng 3D)","yccd":"1. Năng lực mĩ thuật\n- Củng cố cách nhận biết sự kết hợp của các hình cơ bản trong đồ vật, sự vật.\n- Tạo được một vật có sự kết hợp của hình cơ bản dạng 3D bằng hình thức nặn hoặc tạo khối.\n- Biết sử dụng công cụ, vật liệu phù hợp để thực hành.\n2. Năng lực chung\n- Giải quyết vấn đề và sáng tạo: sắp xếp, kết hợp các hình để tạo vật 3D theo ý thích.\n- Giao tiếp và hợp tác: liên tưởng, trao đổi ý tưởng với bạn.\n3. Phẩm chất\n- Chăm chỉ, kiên trì hoàn thành sản phẩm; yêu thích sáng tạo hình khối.","dodung":"- Giáo viên: một số sản phẩm 3D kết hợp hình cơ bản; đất nặn, vật liệu tạo khối; thiết bị trình chiếu.\n- Học sinh: sản phẩm tiết 1, đất nặn, giấy bìa, bút màu, kéo, hồ dán, vật liệu tái sử dụng.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV kiểm tra đồ dùng và sản phẩm tiết 1 của HS, khen ngợi, động viên.\n- GV tổ chức trò chơi Hình gì - Vật gì: liên tưởng một đồ vật có hình tương ứng với một hình cơ bản, dẫn vào phần thể hiện.","hs":"- HS trưng bày sản phẩm tiết 1.\n- HS tham gia trò chơi, liên tưởng đồ vật."},{"ten":"2. Khám phá — Liên hệ thực tế","gv":"- GV gợi ý HS tự tìm và liên hệ các vật trong cuộc sống có dạng kết hợp của các hình cơ bản.\n- GV chốt: các hình cơ bản kết hợp với nhau (phép cộng hoặc lặp lại) giúp liên tưởng đến nhiều vật; có thể dùng nhiều chất liệu để thể hiện.","hs":"- HS kể các vật kết hợp từ hình cơ bản.\n- HS lắng nghe, ghi nhớ."},{"ten":"3. Luyện tập — Sáng tạo (3D)","gv":"- GV hướng dẫn HS quan sát cách tạo khối bằng đất nặn hoặc vật liệu.\n- GV yêu cầu HS thực hành nặn, ghép tạo một vật có sự kết hợp của các hình cơ bản dạng 3D.\n- GV quan sát, giúp đỡ; nhắc HS lưu giữ sản phẩm cho tiết 3.","hs":"- HS quan sát, tiếp thu cách làm.\n- HS thực hành tạo vật 3D từ các hình cơ bản.\n- HS lưu giữ sản phẩm."},{"ten":"4. Vận dụng","gv":"- GV cho HS giới thiệu nhanh sản phẩm 3D đang làm.\n- GV khen ngợi, động viên, dặn chuẩn bị cho tiết 3.","hs":"- HS giới thiệu sản phẩm.\n- HS ghi nhớ nhiệm vụ."}]},
{"lop":2,"mon":"Mĩ thuật","tuan":6,"tiet":6,"bai":"Chủ đề 3: SỰ KẾT HỢP CỦA CÁC HÌNH CƠ BẢN — Tiết 3: Thảo luận và vận dụng (xem tranh họa sĩ)","yccd":"1. Năng lực mĩ thuật\n- Củng cố kiến thức về hình cơ bản và sự kết hợp của chúng để tạo sản phẩm mĩ thuật.\n- Quan sát, tìm hiểu tranh của họa sĩ Pôn Cli (Paul Klee): Lâu đài và mặt trời, Những chiếc thuyền buồm; nhận ra sự kết hợp các hình cơ bản trong tranh.\n- Vẽ được một bức tranh có sử dụng sự kết hợp các hình cơ bản và vẽ màu theo ý thích.\n2. Năng lực chung\n- Giao tiếp và hợp tác: trao đổi, nêu cảm nhận về tác phẩm và sản phẩm của bạn.\n3. Phẩm chất\n- Yêu thích tác phẩm mĩ thuật; trân trọng sự sáng tạo trong nghệ thuật.\n4. Tích hợp\n- Năng lực số 1.1 CB1 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS nêu được cách hoạ sĩ kết hợp hình và màu khi xem tranh phóng to.","dodung":"- Giáo viên: tranh Lâu đài và mặt trời, Những chiếc thuyền buồm của họa sĩ Pôn Cli; thiết bị trình chiếu học liệu số.\n- Học sinh: sản phẩm các tiết trước, bút chì, tẩy, màu vẽ, giấy vẽ.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV kiểm tra sản phẩm tiết 2, khen ngợi, động viên.\n- GV giới thiệu nội dung tiết học: xem tranh họa sĩ và sáng tạo tranh của em.","hs":"- HS trưng bày sản phẩm tiết 2.\n- HS lắng nghe, mở bài học."},{"ten":"2. Khám phá — Xem tranh họa sĩ","gv":"- GV cho HS quan sát tranh trang 18 SGK Mĩ thuật 2, đặt câu hỏi: Trong tranh Lâu đài và mặt trời có hình ảnh nào nổi bật? Lâu đài, thuyền buồm được kết hợp từ hình cơ bản nào? Em có nhận xét gì về màu sắc?\n- GV giới thiệu ngắn gọn về họa sĩ Pôn Cli và hai bức tranh.","hs":"- HS quan sát tranh, trả lời câu hỏi.\n- HS nhận ra sự kết hợp hình cơ bản và màu sắc trong tranh.\n- HS lắng nghe, ghi nhớ."},{"ten":"3. Luyện tập — Sáng tạo","gv":"- GV yêu cầu HS vẽ một bức tranh có sử dụng sự kết hợp của các hình cơ bản đã học và vẽ màu theo ý thích.\n- GV gợi ý về nội dung, cách chọn hình ảnh, màu sắc; quan sát, giúp đỡ HS hoàn thiện.","hs":"- HS vẽ tranh từ các hình cơ bản.\n- HS vẽ màu, hoàn thiện sản phẩm."},{"ten":"4. Vận dụng — Trưng bày","gv":"- GV tổ chức cho HS trưng bày, chia sẻ: Sản phẩm được tạo từ những hình nào? Màu sắc thế nào? Em thích sản phẩm nào nhất?\n- GV cùng HS nhận xét, động viên; dặn xem trước Chủ đề 4.","hs":"- HS trưng bày, giới thiệu tranh.\n- HS nhận xét, ghi nhớ nhiệm vụ."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV chiếu bản chụp rõ nét bức tranh của hoạ sĩ Pôn Cli, phóng to từng mảng để HS thấy hoạ sĩ đã xếp các hình vuông, hình tam giác cạnh nhau và chọn màu nóng, màu lạnh thế nào; tranh in trong sách nhỏ, phóng to trên màn hình mới nhìn rõ từng mảng màu.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV chỉ dòng chữ ghi tên tranh và tên hoạ sĩ đặt cạnh bức tranh, giải thích xem tranh của ai thì phải nói rõ tranh của người ấy, cũng như bài của em thì ghi tên em.\n⚠ (Miền 4: An toàn) Bức tranh này là của hoạ sĩ, ta chỉ xem để học cách hoạ sĩ ghép hình chứ không vẽ lại y hệt rồi nói là tranh của mình; ảnh tranh do GV tải sẵn từ nguồn đáng tin.","hs":"- HS nêu được cách hoạ sĩ kết hợp hình và màu khi xem tranh phóng to.\n- HS hiểu vì sao phải ghi tên tác giả khi nói về một bức tranh."}]},
{"lop":2,"mon":"Mĩ thuật","tuan":7,"tiet":7,"bai":"Chủ đề 4: NHỮNG MẢNG MÀU YÊU THÍCH — Tiết 1: Quan sát và thể hiện mảng màu","yccd":"1. Năng lực mĩ thuật\n- Nhận biết được màu sắc trong cuộc sống và trong tác phẩm mĩ thuật.\n- Tạo được những mảng màu yêu thích bằng hình thức tự chọn (vẽ, xé dán, in...).\n- Bước đầu nhận biết cách sắp đặt các màu cạnh nhau.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động lựa chọn màu sắc, hình thức thể hiện.\n- Giao tiếp và hợp tác: chia sẻ về những màu em yêu thích.\n3. Phẩm chất\n- Yêu thích màu sắc; cảm nhận cái đẹp của màu sắc trong cuộc sống.\n4. Tích hợp\n- Năng lực số 1.1 CB1 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS nhận ra sự chuyển dần của màu trên bảng màu số.","dodung":"- Giáo viên: bảng màu, tranh ảnh có màu sắc phong phú; tác phẩm hội họa nhiều màu; thiết bị trình chiếu.\n- Học sinh: SGK Mĩ thuật 2, Vở bài tập Mĩ thuật 2, màu vẽ, giấy vẽ, giấy màu, kéo, hồ dán.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS chơi trò chơi Gọi tên màu sắc quanh em: nhìn nhanh đồ vật trong lớp và gọi tên màu.\n- GV nhận xét, tuyên dương, giới thiệu chủ đề.","hs":"- HS tham gia trò chơi, gọi tên màu sắc.\n- HS lắng nghe, mở bài học."},{"ten":"2. Khám phá — Màu sắc trong cuộc sống","gv":"- GV cho HS quan sát hình ảnh trang 19-20 SGK Mĩ thuật 2 và tranh ảnh nhiều màu.\n- GV đặt câu hỏi: Em thấy những màu nào? Màu nào em yêu thích? Các màu đứng cạnh nhau tạo cảm giác gì?\n- GV chốt: màu sắc rất phong phú, mỗi màu gợi một cảm xúc riêng.","hs":"- HS quan sát, kể tên màu sắc.\n- HS nêu màu yêu thích, cảm nhận về màu.\n- HS lắng nghe, ghi nhớ."},{"ten":"3. Luyện tập — Sáng tạo","gv":"- GV hướng dẫn HS tham khảo cách tạo mảng màu trong SGK (vẽ, xé dán, in).\n- GV yêu cầu HS tạo những mảng màu yêu thích bằng hình thức tự chọn.\n- GV quan sát, giúp đỡ; nhắc HS lưu giữ sản phẩm cho tiết sau.","hs":"- HS tham khảo, chọn hình thức thể hiện.\n- HS thực hành tạo những mảng màu yêu thích.\n- HS lưu giữ sản phẩm."},{"ten":"4. Vận dụng","gv":"- GV cho HS chia sẻ: em đã tạo những mảng màu nào? Vì sao em thích?\n- GV khen ngợi, dặn HS chuẩn bị cho tiết 2.","hs":"- HS chia sẻ về mảng màu của mình.\n- HS ghi nhớ nhiệm vụ."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV chiếu một bảng màu số và di chuyển ô chọn để HS thấy màu chuyển dần từ đỏ sang cam rồi sang vàng; sự chuyển màu liên tục này hộp sáp chỉ có mấy màu rời rạc không cho thấy được.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) HS chỉ trên bảng màu hai màu đứng cạnh nhau nhìn hoà hợp và hai màu đứng xa nhau nhìn tương phản mạnh.\n⚠ (Miền 4: An toàn) GV thao tác trên máy; màu trên màn hình sáng hơn màu sáp trên giấy nên HS phải thử màu thật ra giấy nháp trước khi tô vào bài.","hs":"- HS nhận ra sự chuyển dần của màu trên bảng màu số.\n- HS chọn được cặp màu hoà hợp và cặp màu tương phản cho bài của mình."}]},
{"lop":2,"mon":"Mĩ thuật","tuan":8,"tiet":8,"bai":"Chủ đề 4: NHỮNG MẢNG MÀU YÊU THÍCH — Tiết 2: Màu đậm, màu nhạt","yccd":"1. Năng lực mĩ thuật\n- Nhận biết màu sắc trong tác phẩm hội họa, chú ý đến sự sắp đặt các màu cạnh nhau, màu đậm, màu nhạt.\n- Tạo được những mảng màu thể hiện được màu đậm, màu nhạt.\n- Biết phối hợp màu đậm - nhạt để sản phẩm thêm sinh động.\n2. Năng lực chung\n- Giải quyết vấn đề và sáng tạo: lựa chọn, sắp xếp mảng màu đậm - nhạt hợp lí.\n- Giao tiếp và hợp tác: trao đổi cảm nhận về màu sắc với bạn.\n3. Phẩm chất\n- Chăm chỉ hoàn thành sản phẩm; yêu thích khám phá màu sắc.\n4. Tích hợp\n- Năng lực số 1.1 CB1 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS nhận ra một màu có nhiều mức đậm nhạt khi xem ảnh được chỉnh sáng.","dodung":"- Giáo viên: tác phẩm hội họa có màu đậm, màu nhạt; bảng pha màu; thiết bị trình chiếu.\n- Học sinh: sản phẩm tiết 1, màu vẽ, giấy vẽ, giấy màu.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV kiểm tra đồ dùng và sản phẩm tiết 1, khen ngợi, động viên.\n- GV cho HS so sánh nhanh hai mảng màu đậm - nhạt, dẫn vào bài.","hs":"- HS trưng bày sản phẩm tiết 1.\n- HS quan sát, so sánh màu đậm - nhạt."},{"ten":"2. Khám phá — Màu đậm, màu nhạt","gv":"- GV cho HS quan sát tác phẩm hội họa, chỉ ra chỗ màu đậm, màu nhạt và cách các màu đứng cạnh nhau.\n- GV đặt câu hỏi: Màu nào đậm? Màu nào nhạt? Khi đặt cạnh nhau, chúng tạo cảm giác gì?\n- GV chốt: kết hợp màu đậm - nhạt làm bức tranh sinh động hơn.","hs":"- HS quan sát, chỉ ra màu đậm, màu nhạt.\n- HS trả lời câu hỏi.\n- HS lắng nghe, ghi nhớ."},{"ten":"3. Luyện tập — Sáng tạo","gv":"- GV yêu cầu HS tạo những mảng màu thể hiện rõ màu đậm, màu nhạt.\n- GV gợi ý cách pha màu để có sắc đậm - nhạt; quan sát, giúp đỡ HS.","hs":"- HS thực hành tạo mảng màu đậm - nhạt.\n- HS hoàn thiện sản phẩm."},{"ten":"4. Vận dụng","gv":"- GV cho HS chia sẻ: sản phẩm của em có màu đậm, nhạt ở đâu?\n- GV khen ngợi, dặn HS chuẩn bị cho tiết 3.","hs":"- HS chia sẻ về màu đậm - nhạt trong sản phẩm.\n- HS ghi nhớ nhiệm vụ."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở một bức ảnh trong phần mềm xem ảnh rồi kéo thanh chỉnh độ sáng để cả bức chuyển từ đậm sang nhạt ngay trước mắt HS; kéo qua kéo lại vài lần cho HS thấy cùng một màu vẫn có nhiều mức đậm nhạt.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) HS chỉ ra trong ảnh chỗ nào đậm nhất, chỗ nào nhạt nhất và nói chỗ đậm đã làm hình nổi lên thế nào.\n⚠ (Miền 4: An toàn) GV điều khiển thanh chỉnh sáng; sau đó HS pha thêm nước hoặc tô chồng lớp trên giấy để tự tạo độ đậm nhạt bằng tay, màn hình chỉ giúp nhìn thấy trước kết quả.","hs":"- HS nhận ra một màu có nhiều mức đậm nhạt khi xem ảnh được chỉnh sáng.\n- HS tạo được mảng đậm, mảng nhạt trên bài vẽ của mình."}]},
{"lop":2,"mon":"Mĩ thuật","tuan":9,"tiet":9,"bai":"Chủ đề 4: NHỮNG MẢNG MÀU YÊU THÍCH — Tiết 3: Thảo luận và vận dụng","yccd":"1. Năng lực mĩ thuật\n- Củng cố kiến thức về màu sắc, màu đậm, màu nhạt đã học.\n- Sử dụng những mảng màu yêu thích để trang trí một đồ vật.\n- Nêu được cảm nhận về màu sắc trong sản phẩm của mình và của bạn.\n2. Năng lực chung\n- Giao tiếp và hợp tác: trao đổi nhóm, trình bày cảm nhận.\n- Giải quyết vấn đề và sáng tạo: chọn màu phù hợp để trang trí đồ vật.\n3. Phẩm chất\n- Yêu thích cái đẹp; giữ gìn, trân trọng sản phẩm do mình tạo ra.\n4. Tích hợp\n- Năng lực số 1.1 CB1 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS lấy được ý tưởng sắp xếp mảng màu từ bộ ảnh đồ vật.","dodung":"- Giáo viên: đồ vật để trang trí bằng mảng màu; sản phẩm mẫu; thiết bị trình chiếu.\n- Học sinh: sản phẩm các tiết trước, màu vẽ, giấy màu, đồ vật để trang trí, kéo, hồ dán.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV kiểm tra sản phẩm tiết 2, khen ngợi, động viên.\n- GV giới thiệu nội dung tiết học.","hs":"- HS trưng bày sản phẩm tiết 2.\n- HS lắng nghe, mở bài học."},{"ten":"2. Khám phá — Thảo luận","gv":"- GV tổ chức cho HS trao đổi nhóm: Bài của bạn dùng những màu nào? Có màu đậm, nhạt không? Em thích mảng màu nào?\n- GV bổ sung câu hỏi và chốt kiến thức về sự sắp đặt màu.","hs":"- HS thảo luận nhóm, trả lời câu hỏi.\n- HS lắng nghe, ghi nhớ."},{"ten":"3. Luyện tập — Vận dụng","gv":"- GV gợi ý HS dùng những mảng màu yêu thích để trang trí một đồ vật (hộp bút, khung ảnh, tấm bìa...).\n- GV quan sát, giúp đỡ HS hoàn thiện sản phẩm.","hs":"- HS thực hành trang trí đồ vật bằng mảng màu.\n- HS hoàn thiện sản phẩm."},{"ten":"4. Vận dụng — Trưng bày","gv":"- GV tổ chức trưng bày, chia sẻ: Bạn dùng màu gì trang trí? Em thích sản phẩm nào nhất?\n- GV cùng HS nhận xét, động viên; dặn xem trước Chủ đề 5.","hs":"- HS trưng bày, giới thiệu sản phẩm.\n- HS nhận xét, ghi nhớ nhiệm vụ."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV chiếu bộ ảnh đồ vật quen thuộc được trang trí bằng mảng màu: cặp sách, hộp bút, chiếc quạt giấy, tấm rèm; mỗi ảnh có ghi tên người làm hoặc nơi cung cấp ảnh.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV nêu rõ mỗi mẫu trang trí đều do một người nghĩ ra; HS xem để lấy ý tưởng rồi tự nghĩ cách sắp xếp mảng màu của riêng mình chứ không vẽ lại y hệt mẫu.\n⚠ (Miền 4: An toàn) Ảnh mẫu do GV chọn sẵn, HS không xin chụp lại ảnh mẫu bằng điện thoại; lấy ý tưởng từ mẫu thì được, chép nguyên mẫu rồi nhận là của mình thì không được.","hs":"- HS lấy được ý tưởng sắp xếp mảng màu từ bộ ảnh đồ vật.\n- HS nêu được điểm khác giữa bài của mình với mẫu đã xem."}]},
{"lop":2,"mon":"Mĩ thuật","tuan":10,"tiet":10,"bai":"Chủ đề 5: SỰ KẾT HỢP THÚ VỊ CỦA KHỐI — Tiết 1: Quan sát và thể hiện khối","yccd":"1. Năng lực mĩ thuật\n- Liên tưởng được sự kết hợp của khối đến những vật trong cuộc sống.\n- Tạo được một sản phẩm mĩ thuật có sự kết hợp của khối bằng đất nặn hoặc vật liệu.\n- Bước đầu nhận biết khối cầu, khối trụ, khối hộp trong đồ vật.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động quan sát, liên tưởng và lựa chọn vật liệu.\n- Giao tiếp và hợp tác: chia sẻ ý tưởng tạo khối với bạn.\n3. Phẩm chất\n- Yêu thích tạo hình khối; chăm chỉ, sáng tạo.\n4. Tích hợp\n- Năng lực số 1.1 CB1 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS nhận ra các khối cơ bản trong một hình dáng phức tạp qua mô hình xoay.","dodung":"- Giáo viên: một số đồ vật dạng khối (khối cầu, trụ, hộp); sản phẩm mĩ thuật từ khối; đất nặn; thiết bị trình chiếu.\n- Học sinh: SGK Mĩ thuật 2, Vở bài tập Mĩ thuật 2, đất nặn, vật liệu tái sử dụng, bút màu, kéo, hồ dán.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS chơi trò chơi Sờ vật đoán khối: sờ đồ vật trong túi và đoán đó là khối gì.\n- GV nhận xét, tuyên dương, giới thiệu chủ đề.","hs":"- HS tham gia trò chơi, đoán khối.\n- HS lắng nghe, mở bài học."},{"ten":"2. Khám phá — Quan sát khối","gv":"- GV cho HS quan sát đồ vật dạng khối và hình trong SGK Mĩ thuật 2.\n- GV đặt câu hỏi: Đồ vật này có dạng khối gì? Sự kết hợp của khối gợi em liên tưởng đến vật gì?\n- GV chốt: khối kết hợp với nhau tạo nên hình dạng nhiều đồ vật, con vật.","hs":"- HS quan sát, trả lời câu hỏi.\n- HS liên tưởng khối đến các vật trong cuộc sống.\n- HS lắng nghe, ghi nhớ."},{"ten":"3. Luyện tập — Sáng tạo","gv":"- GV hướng dẫn HS tham khảo cách tạo sản phẩm từ khối trong SGK.\n- GV yêu cầu HS thực hành nặn hoặc ghép tạo một sản phẩm mĩ thuật có sự kết hợp của khối.\n- GV quan sát, giúp đỡ; nhắc HS lưu giữ sản phẩm cho tiết sau.","hs":"- HS tham khảo, tiếp thu cách làm.\n- HS thực hành tạo sản phẩm từ khối.\n- HS lưu giữ sản phẩm."},{"ten":"4. Vận dụng","gv":"- GV cho HS chia sẻ: sản phẩm của em kết hợp những khối nào?\n- GV khen ngợi, dặn HS chuẩn bị cho tiết 2.","hs":"- HS chia sẻ về sản phẩm.\n- HS ghi nhớ nhiệm vụ."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV chiếu mô hình ba chiều một con vật, một chiếc xe và xoay chậm, đồng thời tách dần từng khối cầu, khối trụ, khối hộp tạo nên nó; HS nhìn thấy bên trong một hình dáng phức tạp chỉ là mấy khối đơn giản ghép lại.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) HS chọn một đồ vật trong lớp và đoán đồ vật đó gồm những khối nào.\n⚠ (Miền 4: An toàn) GV thao tác xoay và tách khối; xem xong HS cầm hộp giấy, quả bóng, ống giấy thật để ghép thử bằng tay.","hs":"- HS nhận ra các khối cơ bản trong một hình dáng phức tạp qua mô hình xoay.\n- HS đoán được các khối tạo nên một đồ vật thật."}]},
{"lop":2,"mon":"Mĩ thuật","tuan":11,"tiet":11,"bai":"Chủ đề 5: SỰ KẾT HỢP THÚ VỊ CỦA KHỐI — Tiết 2: Sắp xếp các khối","yccd":"1. Năng lực mĩ thuật\n- Liên tưởng được sự sắp xếp của khối đến những vật trong cuộc sống.\n- Sắp xếp các khối tạo nên một sản phẩm mĩ thuật yêu thích.\n- Biết sắp đặt các khối cân đối, hài hòa.\n2. Năng lực chung\n- Giải quyết vấn đề và sáng tạo: sắp xếp khối theo ý tưởng riêng.\n- Giao tiếp và hợp tác: phối hợp với bạn khi tạo sản phẩm.\n3. Phẩm chất\n- Chăm chỉ, kiên trì; yêu thích tạo hình từ khối.","dodung":"- Giáo viên: sản phẩm mĩ thuật sắp xếp từ khối; đất nặn, vật liệu; thiết bị trình chiếu.\n- Học sinh: sản phẩm tiết 1, đất nặn, vật liệu tái sử dụng, bút màu, kéo, hồ dán.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV kiểm tra sản phẩm tiết 1, khen ngợi, động viên.\n- GV cho HS xem một sản phẩm sắp xếp từ nhiều khối, dẫn vào bài.","hs":"- HS trưng bày sản phẩm tiết 1.\n- HS quan sát, lắng nghe."},{"ten":"2. Khám phá — Sắp xếp khối","gv":"- GV gợi ý HS quan sát cách sắp xếp khối trong SGK và sản phẩm mẫu.\n- GV đặt câu hỏi: Các khối được sắp xếp thế nào? Gợi em liên tưởng đến vật gì? Làm sao để sắp xếp cân đối?\n- GV chốt cách sắp đặt khối hài hòa.","hs":"- HS quan sát, trả lời câu hỏi.\n- HS nhận biết cách sắp xếp khối cân đối.\n- HS lắng nghe, ghi nhớ."},{"ten":"3. Luyện tập — Sáng tạo","gv":"- GV yêu cầu HS sắp xếp các khối để tạo một sản phẩm mĩ thuật yêu thích.\n- GV gợi ý cách chọn khối, sắp đặt cân đối; quan sát, giúp đỡ HS.\n- GV nhắc HS lưu giữ sản phẩm cho tiết 3.","hs":"- HS thực hành sắp xếp khối tạo sản phẩm.\n- HS hoàn thiện, lưu giữ sản phẩm."},{"ten":"4. Vận dụng","gv":"- GV cho HS chia sẻ: em sắp xếp các khối thành hình gì?\n- GV khen ngợi, dặn HS chuẩn bị cho tiết 3.","hs":"- HS chia sẻ về sản phẩm.\n- HS ghi nhớ nhiệm vụ."}]},
{"lop":2,"mon":"Mĩ thuật","tuan":12,"tiet":12,"bai":"Chủ đề 5: SỰ KẾT HỢP THÚ VỊ CỦA KHỐI — Tiết 3: Thảo luận và vận dụng (sản phẩm nhóm)","yccd":"1. Năng lực mĩ thuật\n- Củng cố kiến thức về khối và sự kết hợp của khối đã học.\n- Sắp xếp các khối theo một chủ đề để tạo sản phẩm nhóm.\n- Nêu được cảm nhận về sản phẩm của mình và của nhóm bạn.\n2. Năng lực chung\n- Giao tiếp và hợp tác: phối hợp trong nhóm để tạo sản phẩm chung theo chủ đề.\n3. Phẩm chất\n- Đoàn kết, biết chia sẻ công việc; trân trọng sản phẩm chung.\n4. Tích hợp\n- Năng lực số 1.3 CB1 (Quản lí dữ liệu, thông tin và nội dung số): HS nêu được cách sắp xếp cao thấp, thưa dày cho mô hình nhóm.","dodung":"- Giáo viên: sản phẩm nhóm mẫu; đất nặn, vật liệu; thiết bị trình chiếu.\n- Học sinh: sản phẩm các tiết trước, đất nặn, vật liệu tái sử dụng, bút màu, kéo, hồ dán.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV kiểm tra sản phẩm tiết 2, khen ngợi, động viên.\n- GV giới thiệu nội dung tiết học: tạo sản phẩm nhóm theo chủ đề.","hs":"- HS trưng bày sản phẩm tiết 2.\n- HS lắng nghe, mở bài học."},{"ten":"2. Khám phá — Thảo luận","gv":"- GV tổ chức cho HS thảo luận nhóm: Nhóm em sẽ tạo chủ đề gì (khu vườn, thành phố, sở thú...)? Cần những khối nào?\n- GV bổ sung, chốt cách phối hợp trong nhóm.","hs":"- HS thảo luận, chọn chủ đề nhóm.\n- HS phân công công việc, lắng nghe."},{"ten":"3. Luyện tập — Sáng tạo nhóm","gv":"- GV yêu cầu các nhóm sắp xếp các khối theo chủ đề đã chọn để tạo sản phẩm chung.\n- GV quan sát, giúp đỡ các nhóm hoàn thiện.","hs":"- HS phối hợp trong nhóm tạo sản phẩm theo chủ đề.\n- HS hoàn thiện sản phẩm nhóm."},{"ten":"4. Vận dụng — Trưng bày","gv":"- GV tổ chức cho các nhóm trưng bày, giới thiệu sản phẩm theo chủ đề.\n- GV cùng HS nhận xét, động viên; dặn xem trước Chủ đề 6.","hs":"- HS trưng bày, giới thiệu sản phẩm nhóm.\n- HS nhận xét, ghi nhớ nhiệm vụ."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV chiếu ảnh chụp từ trên cao một khu vườn, một góc phố để nhóm HS thấy cách người ta sắp xếp: chỗ nào cao, chỗ nào thấp, chỗ nào để trống làm lối đi.\n- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 1) Mỗi nhóm bàn nhau chọn một cách sắp xếp và phân công ai làm khối nào; GV chụp ảnh mô hình của nhóm ở giữa giờ để nhóm nhìn lại tổng thể và chỉnh cho cân đối.\n⚠ (Miền 4: An toàn) Ảnh chụp mô hình chỉ dùng để nhóm tự chỉnh sản phẩm, không đưa ra ngoài lớp; khi bàn bạc, mỗi bạn đều được nói, không giành làm hết phần của bạn khác.","hs":"- HS nêu được cách sắp xếp cao thấp, thưa dày cho mô hình nhóm.\n- HS nhìn ảnh chụp giữa giờ và chỉnh lại mô hình cho cân đối."}]},
{"lop":2,"mon":"Mĩ thuật","tuan":13,"tiet":13,"bai":"Chủ đề 6: SẮC MÀU THIÊN NHIÊN — Tiết 1: Quan sát và thể hiện sắc màu","yccd":"1. Năng lực mĩ thuật\n- Nhận biết được màu sắc trong thiên nhiên, cuộc sống.\n- Làm một sản phẩm mĩ thuật thể hiện sắc màu trong cuộc sống mình yêu thích (hình thức xé, dán, nặn).\n- Bước đầu cảm nhận vẻ đẹp của sắc màu thiên nhiên.\n2. Năng lực chung\n- Tự chủ và tự học: quan sát thiên nhiên, lựa chọn màu và hình thức thể hiện.\n- Giao tiếp và hợp tác: chia sẻ cảm nhận về sắc màu thiên nhiên.\n3. Phẩm chất\n- Yêu thiên nhiên; có ý thức bảo vệ môi trường, cảnh quan xung quanh.\n4. Tích hợp\n- Năng lực số 1.1 CB1 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS nêu được màu chủ đạo của từng mùa sau khi xem phim tua nhanh.","dodung":"- Giáo viên: tranh ảnh thiên nhiên nhiều màu (bầu trời, cây cối, hoa lá, cánh đồng); thiết bị trình chiếu.\n- Học sinh: SGK Mĩ thuật 2, Vở bài tập Mĩ thuật 2, màu vẽ, giấy vẽ, giấy màu, đất nặn, kéo, hồ dán, lá cây, cành hoa khô.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS xem nhanh hình ảnh thiên nhiên và hỏi: Em thấy những màu nào trong thiên nhiên?\n- GV nhận xét, giới thiệu chủ đề.","hs":"- HS quan sát, kể tên màu sắc thiên nhiên.\n- HS lắng nghe, mở bài học."},{"ten":"2. Khám phá — Sắc màu thiên nhiên","gv":"- GV cho HS quan sát hình trong SGK Mĩ thuật 2 và tranh ảnh thiên nhiên.\n- GV đặt câu hỏi: Bầu trời, cây cối, hoa lá có màu gì? Sắc màu nào em yêu thích nhất?\n- GV chốt: thiên nhiên có sắc màu phong phú, tươi đẹp.","hs":"- HS quan sát, trả lời câu hỏi.\n- HS nêu sắc màu yêu thích.\n- HS lắng nghe, ghi nhớ."},{"ten":"3. Luyện tập — Sáng tạo","gv":"- GV hướng dẫn HS tham khảo cách làm sản phẩm bằng xé, dán, nặn trong SGK.\n- GV yêu cầu HS làm một sản phẩm thể hiện sắc màu thiên nhiên mình yêu thích.\n- GV quan sát, giúp đỡ; nhắc HS lưu giữ sản phẩm cho tiết sau.","hs":"- HS tham khảo, chọn hình thức thể hiện.\n- HS thực hành làm sản phẩm về sắc màu thiên nhiên.\n- HS lưu giữ sản phẩm."},{"ten":"4. Vận dụng","gv":"- GV cho HS chia sẻ: sản phẩm của em thể hiện sắc màu gì của thiên nhiên?\n- GV khen ngợi, dặn HS chuẩn bị cho tiết 2.","hs":"- HS chia sẻ về sản phẩm.\n- HS ghi nhớ nhiệm vụ."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV chiếu đoạn phim tua nhanh một cây thay lá qua bốn mùa: xanh non, xanh đậm, vàng, trơ cành; cả năm trời được nén trong một phút nên HS thấy được sự đổi màu mà quan sát ngoài sân trong một tiết học không thể thấy.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) HS gọi tên màu chủ đạo của từng mùa và liên hệ với cây cối ở quê mình.\n⚠ (Miền 4: An toàn) GV mở đúng đoạn phim đã tải sẵn, không mở trang chia sẻ phim có nội dung gợi ý chen ngang; xem phim xong HS ra sân quan sát một cái cây thật để đối chiếu.","hs":"- HS nêu được màu chủ đạo của từng mùa sau khi xem phim tua nhanh.\n- HS kể được sự đổi màu của cây cối ở nơi mình sống."}]},
{"lop":2,"mon":"Mĩ thuật","tuan":14,"tiet":14,"bai":"Chủ đề 6: SẮC MÀU THIÊN NHIÊN — Tiết 2: Vẽ tranh sắc màu thiên nhiên","yccd":"1. Năng lực mĩ thuật\n- Nhận biết màu sắc trong tác phẩm hội họa về thiên nhiên.\n- Vẽ được một bức tranh thể hiện vẻ sắc màu thiên nhiên (chú ý màu đậm, màu nhạt, sự kết hợp của màu).\n- Biết phối màu để tranh thêm sinh động.\n2. Năng lực chung\n- Giải quyết vấn đề và sáng tạo: chọn nội dung và màu sắc phù hợp để vẽ tranh.\n- Giao tiếp và hợp tác: chia sẻ cảm nhận về tranh của bạn.\n3. Phẩm chất\n- Yêu thiên nhiên; chăm chỉ, kiên trì hoàn thành tranh.","dodung":"- Giáo viên: tác phẩm hội họa về thiên nhiên; tranh mẫu; thiết bị trình chiếu.\n- Học sinh: sản phẩm tiết 1, màu vẽ, giấy vẽ.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV kiểm tra sản phẩm tiết 1, khen ngợi, động viên.\n- GV cho HS xem một bức tranh phong cảnh, dẫn vào bài.","hs":"- HS trưng bày sản phẩm tiết 1.\n- HS quan sát, lắng nghe."},{"ten":"2. Khám phá — Xem tranh thiên nhiên","gv":"- GV cho HS quan sát tác phẩm hội họa về thiên nhiên.\n- GV đặt câu hỏi: Tranh có những màu nào? Đâu là màu đậm, màu nhạt? Các màu kết hợp thế nào?\n- GV chốt về cách phối màu trong tranh phong cảnh.","hs":"- HS quan sát, trả lời câu hỏi.\n- HS nhận biết màu đậm, nhạt và cách kết hợp.\n- HS lắng nghe, ghi nhớ."},{"ten":"3. Luyện tập — Sáng tạo","gv":"- GV yêu cầu HS vẽ một bức tranh thể hiện sắc màu thiên nhiên (cây cối, hoa lá, bầu trời...).\n- GV gợi ý cách chọn màu, phối màu đậm - nhạt; quan sát, giúp đỡ HS.\n- GV nhắc HS lưu giữ tranh cho tiết 3.","hs":"- HS vẽ tranh sắc màu thiên nhiên.\n- HS phối màu, hoàn thiện, lưu giữ tranh."},{"ten":"4. Vận dụng","gv":"- GV cho HS chia sẻ: tranh của em thể hiện cảnh thiên nhiên nào?\n- GV khen ngợi, dặn HS chuẩn bị cho tiết 3.","hs":"- HS chia sẻ về tranh.\n- HS ghi nhớ nhiệm vụ."}]},
{"lop":2,"mon":"Mĩ thuật","tuan":15,"tiet":15,"bai":"Chủ đề 6: SẮC MÀU THIÊN NHIÊN — Tiết 3: Trang trí bằng hình thức in","yccd":"1. Năng lực mĩ thuật\n- Củng cố kiến thức về sắc màu thiên nhiên đã học.\n- Trang trí một đồ vật bằng hình thức in (từ củ, quả, lá cây).\n- Biết tạo họa tiết lặp lại bằng cách in để trang trí.\n2. Năng lực chung\n- Giải quyết vấn đề và sáng tạo: lựa chọn vật liệu tự nhiên để in họa tiết.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ cách in với bạn.\n3. Phẩm chất\n- Yêu thiên nhiên; có ý thức sử dụng vật liệu tự nhiên để sáng tạo.","dodung":"- Giáo viên: sản phẩm in mẫu; củ, quả, lá cây; màu nước; thiết bị trình chiếu.\n- Học sinh: sản phẩm các tiết trước, lá cây, củ quả, màu nước, giấy, đồ vật để trang trí.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV kiểm tra sản phẩm tiết 2, khen ngợi, động viên.\n- GV cho HS xem một sản phẩm in từ lá cây, dẫn vào bài.","hs":"- HS trưng bày sản phẩm tiết 2.\n- HS quan sát, lắng nghe."},{"ten":"2. Khám phá — Kĩ thuật in","gv":"- GV cho HS quan sát cách in từ củ, quả, lá cây và sản phẩm in mẫu.\n- GV đặt câu hỏi: In tạo ra họa tiết gì? Cần chuẩn bị vật liệu nào? Làm sao để họa tiết đẹp?\n- GV thị phạm cách in đơn giản.","hs":"- HS quan sát, trả lời câu hỏi.\n- HS quan sát GV thị phạm, ghi nhớ cách in."},{"ten":"3. Luyện tập — Sáng tạo","gv":"- GV yêu cầu HS trang trí một đồ vật bằng hình thức in (dùng củ, quả, lá cây chấm màu rồi in).\n- GV quan sát, giúp đỡ HS hoàn thiện sản phẩm.","hs":"- HS thực hành in họa tiết để trang trí đồ vật.\n- HS hoàn thiện sản phẩm."},{"ten":"4. Vận dụng — Trưng bày","gv":"- GV tổ chức trưng bày, chia sẻ: Em in bằng vật liệu gì? Họa tiết thế nào?\n- GV cùng HS nhận xét, động viên; dặn chuẩn bị cho tiết sau.","hs":"- HS trưng bày, giới thiệu sản phẩm in.\n- HS nhận xét, ghi nhớ nhiệm vụ."}]},
{"lop":2,"mon":"Mĩ thuật","tuan":16,"tiet":16,"bai":"Chủ đề 6: SẮC MÀU THIÊN NHIÊN — Tiết 4: Trang trí bằng thủ công, kết hợp chất liệu","yccd":"1. Năng lực mĩ thuật\n- Trang trí một đồ vật bằng hình thức thủ công, kết hợp nhiều chất liệu (giấy màu, lá khô, vật liệu tái sử dụng).\n- Hoàn thiện sản phẩm về sắc màu thiên nhiên.\n- Nêu được cảm nhận về sản phẩm của mình và của bạn.\n2. Năng lực chung\n- Giải quyết vấn đề và sáng tạo: kết hợp linh hoạt các chất liệu để trang trí.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ cách làm với bạn.\n3. Phẩm chất\n- Yêu thiên nhiên; tiết kiệm, tận dụng vật liệu tái sử dụng.","dodung":"- Giáo viên: sản phẩm thủ công mẫu kết hợp chất liệu; thiết bị trình chiếu.\n- Học sinh: sản phẩm các tiết trước, giấy màu, lá khô, vật liệu tái sử dụng, kéo, hồ dán, màu vẽ.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV kiểm tra sản phẩm tiết 3, khen ngợi, động viên.\n- GV cho HS xem sản phẩm thủ công kết hợp chất liệu, dẫn vào bài.","hs":"- HS trưng bày sản phẩm tiết 3.\n- HS quan sát, lắng nghe."},{"ten":"2. Khám phá — Kết hợp chất liệu","gv":"- GV cho HS quan sát sản phẩm thủ công kết hợp giấy màu, lá khô, vật liệu tái sử dụng.\n- GV đặt câu hỏi: Sản phẩm dùng những chất liệu gì? Cách kết hợp thế nào cho đẹp?\n- GV chốt cách phối hợp chất liệu.","hs":"- HS quan sát, trả lời câu hỏi.\n- HS nhận biết cách kết hợp chất liệu.\n- HS lắng nghe, ghi nhớ."},{"ten":"3. Luyện tập — Sáng tạo","gv":"- GV yêu cầu HS trang trí một đồ vật bằng hình thức thủ công, kết hợp chất liệu về chủ đề sắc màu thiên nhiên.\n- GV quan sát, giúp đỡ HS hoàn thiện sản phẩm.","hs":"- HS thực hành trang trí thủ công, kết hợp chất liệu.\n- HS hoàn thiện sản phẩm."},{"ten":"4. Vận dụng — Trưng bày","gv":"- GV tổ chức trưng bày, chia sẻ: Em dùng chất liệu gì? Em thích sản phẩm nào nhất?\n- GV cùng HS nhận xét, động viên; dặn chuẩn bị kiểm tra cuối học kì I.","hs":"- HS trưng bày, giới thiệu sản phẩm.\n- HS nhận xét, ghi nhớ nhiệm vụ."}]},
{"lop":2,"mon":"Mĩ thuật","tuan":17,"tiet":17,"bai":"KIỂM TRA, ĐÁNH GIÁ CUỐI HỌC KÌ I","yccd":"1. Năng lực mĩ thuật\n- Vận dụng tổng hợp kiến thức, kĩ năng về nét, hình cơ bản, khối, màu sắc đã học ở học kì I để tạo một sản phẩm mĩ thuật theo chủ đề tự chọn.\n- Trưng bày, giới thiệu và nêu được cảm nhận về sản phẩm của mình.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động hoàn thành sản phẩm đánh giá.\n- Giao tiếp và hợp tác: tự tin giới thiệu sản phẩm trước lớp.\n3. Phẩm chất\n- Chăm chỉ, trung thực trong đánh giá; trân trọng sản phẩm do mình và bạn tạo ra.\n4. Tích hợp\n- Năng lực số 3.2 CB1 (Tích hợp và tinh chỉnh nội dung số): HS xem lại chuỗi sản phẩm của mình trong học kì.","dodung":"- Giáo viên: tiêu chí đánh giá; bảng trưng bày sản phẩm; thiết bị trình chiếu.\n- Học sinh: đồ dùng mĩ thuật đầy đủ (bút chì, màu, giấy, đất nặn, vật liệu tái sử dụng...).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, nêu mục đích tiết kiểm tra, đánh giá cuối học kì I.\n- GV giới thiệu tiêu chí đánh giá đơn giản, gần gũi với HS.","hs":"- HS lắng nghe, nắm mục đích và tiêu chí.\n- HS chuẩn bị đồ dùng."},{"ten":"2. Khám phá — Ôn nhanh kiến thức","gv":"- GV cho HS nhắc lại nhanh các nội dung đã học: nét, hình cơ bản, khối, màu đậm - nhạt, sắc màu thiên nhiên.\n- GV gợi ý HS chọn chủ đề yêu thích để làm sản phẩm.","hs":"- HS nhắc lại kiến thức đã học.\n- HS chọn chủ đề cho sản phẩm."},{"ten":"3. Luyện tập — Thực hành đánh giá","gv":"- GV yêu cầu HS thực hành tạo một sản phẩm mĩ thuật theo chủ đề tự chọn, vận dụng các kiến thức đã học.\n- GV quan sát, giúp đỡ khi cần; đánh giá quá trình và sản phẩm của HS.","hs":"- HS thực hành tạo sản phẩm mĩ thuật.\n- HS hoàn thiện sản phẩm để đánh giá."},{"ten":"4. Vận dụng — Trưng bày, đánh giá","gv":"- GV tổ chức cho HS trưng bày, giới thiệu sản phẩm; nêu cảm nhận.\n- GV nhận xét, đánh giá theo hướng động viên, khích lệ; tổng kết học kì I.","hs":"- HS trưng bày, giới thiệu sản phẩm.\n- HS nêu cảm nhận, lắng nghe nhận xét."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV chụp ảnh sản phẩm của từng HS trong học kì và xếp thành một trang ảnh riêng cho mỗi bạn theo thứ tự thời gian; mở trang của mình, HS thấy được cả quá trình từ bài đầu tiên đến bài mới nhất.\n- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 1) HS nhìn trang ảnh của mình và tự nói một điều mình làm tốt hơn so với hồi đầu năm.\n⚠ (Miền 4: An toàn) Trang ảnh của bạn nào thì chỉ bạn ấy và GV cùng xem; không mang ảnh bài của bạn ra so bì hơn kém trước cả lớp.","hs":"- HS xem lại chuỗi sản phẩm của mình trong học kì.\n- HS tự nêu được một tiến bộ của bản thân."}]},
{"lop":2,"mon":"Mĩ thuật","tuan":18,"tiet":18,"bai":"Chủ đề 7: GƯƠNG MẶT THÂN QUEN — Tiết 1: Quan sát và thể hiện chân dung (2D)","yccd":"1. Năng lực mĩ thuật\n- Quan sát ảnh chân dung để tìm hiểu các bộ phận trên gương mặt (mắt, mũi, miệng, tai, tóc).\n- Thể hiện được một chân dung bằng hình thức 2D (vẽ hoặc xé dán).\n- Bước đầu nhận biết đặc điểm riêng của mỗi gương mặt.\n2. Năng lực chung\n- Tự chủ và tự học: quan sát, ghi nhớ đặc điểm gương mặt để thể hiện.\n- Giao tiếp và hợp tác: chia sẻ về gương mặt người thân, bạn bè.\n3. Phẩm chất\n- Yêu quý, kính trọng người thân; biết quan tâm đến người xung quanh.\n4. Tích hợp\n- Năng lực số 1.1 CB1 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS nêu được vị trí mắt, mũi, miệng trên khuôn mặt nhờ trục kẻ trên ảnh.","dodung":"- Giáo viên: ảnh chân dung; tranh chân dung của họa sĩ; thiết bị trình chiếu.\n- Học sinh: SGK Mĩ thuật 2, Vở bài tập Mĩ thuật 2, bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, hồ dán.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS chơi trò chơi Đoán bạn qua đặc điểm gương mặt.\n- GV nhận xét, giới thiệu chủ đề.","hs":"- HS tham gia trò chơi, đoán bạn.\n- HS lắng nghe, mở bài học."},{"ten":"2. Khám phá — Các bộ phận gương mặt","gv":"- GV cho HS quan sát ảnh chân dung, hình trong SGK Mĩ thuật 2.\n- GV đặt câu hỏi: Trên gương mặt có những bộ phận nào? Mắt, mũi, miệng ở vị trí nào? Điều gì làm mỗi gương mặt khác nhau?\n- GV chốt về các bộ phận và đặc điểm riêng của gương mặt.","hs":"- HS quan sát, trả lời câu hỏi.\n- HS nhận biết các bộ phận và đặc điểm gương mặt.\n- HS lắng nghe, ghi nhớ."},{"ten":"3. Luyện tập — Sáng tạo (2D)","gv":"- GV hướng dẫn HS tham khảo cách thể hiện chân dung trong SGK.\n- GV yêu cầu HS vẽ hoặc xé dán một chân dung (bản thân, bạn hoặc người thân) dạng 2D.\n- GV quan sát, giúp đỡ; nhắc HS lưu giữ sản phẩm cho tiết sau.","hs":"- HS tham khảo, tiếp thu cách làm.\n- HS thực hành thể hiện chân dung 2D.\n- HS lưu giữ sản phẩm."},{"ten":"4. Vận dụng","gv":"- GV cho HS chia sẻ: em vẽ chân dung của ai? Đặc điểm nổi bật là gì?\n- GV khen ngợi, dặn HS chuẩn bị cho tiết 2.","hs":"- HS chia sẻ về chân dung của mình.\n- HS ghi nhớ nhiệm vụ."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV chiếu một bức ảnh chân dung và dùng công cụ vẽ kẻ trục dọc, trục ngang lên ảnh để HS thấy hai mắt nằm ngang nhau ở khoảng giữa khuôn mặt, mũi và miệng nằm trên trục dọc; kẻ rồi xoá đi được nhiều lần, việc mà kẻ lên ảnh giấy không làm được.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) HS soi gương hoặc nhìn bạn cùng bàn để kiểm tra lại nhận xét ấy trên khuôn mặt thật.\n⚠ (Miền 4: An toàn) GV chỉ dùng ảnh chân dung đã chuẩn bị sẵn hoặc ảnh của chính GV; không chiếu ảnh của HS lên màn hình khi chưa hỏi bạn và gia đình bạn.","hs":"- HS nêu được vị trí mắt, mũi, miệng trên khuôn mặt nhờ trục kẻ trên ảnh.\n- HS kiểm tra lại tỉ lệ ấy trên khuôn mặt bạn và của mình."}]},
{"lop":2,"mon":"Mĩ thuật","tuan":19,"tiet":19,"bai":"Chủ đề 7: GƯƠNG MẶT THÂN QUEN — Tiết 2: Thể hiện chân dung (3D)","yccd":"1. Năng lực mĩ thuật\n- Quan sát sản phẩm, tác phẩm mĩ thuật thể hiện về gương mặt.\n- Thể hiện được một chân dung bằng hình thức 3D (nặn hoặc tạo khối).\n- Biết thể hiện đặc điểm gương mặt qua sản phẩm 3D.\n2. Năng lực chung\n- Giải quyết vấn đề và sáng tạo: tạo hình chân dung 3D theo ý tưởng.\n- Giao tiếp và hợp tác: trao đổi cách làm với bạn.\n3. Phẩm chất\n- Yêu quý người thân; kiên trì, chăm chỉ hoàn thành sản phẩm.","dodung":"- Giáo viên: sản phẩm chân dung 3D mẫu; đất nặn; thiết bị trình chiếu.\n- Học sinh: sản phẩm tiết 1, đất nặn, vật liệu tái sử dụng, bút màu.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV kiểm tra sản phẩm tiết 1, khen ngợi, động viên.\n- GV cho HS xem một sản phẩm chân dung 3D, dẫn vào bài.","hs":"- HS trưng bày sản phẩm tiết 1.\n- HS quan sát, lắng nghe."},{"ten":"2. Khám phá — Chân dung 3D","gv":"- GV cho HS quan sát sản phẩm chân dung 3D và hình trong SGK.\n- GV đặt câu hỏi: Sản phẩm thể hiện gương mặt bằng chất liệu gì? Các bộ phận được tạo thế nào?\n- GV chốt cách tạo chân dung 3D.","hs":"- HS quan sát, trả lời câu hỏi.\n- HS nhận biết cách tạo chân dung 3D.\n- HS lắng nghe, ghi nhớ."},{"ten":"3. Luyện tập — Sáng tạo (3D)","gv":"- GV yêu cầu HS nặn hoặc tạo khối một chân dung dạng 3D, thể hiện đặc điểm gương mặt.\n- GV quan sát, giúp đỡ; nhắc HS lưu giữ sản phẩm cho tiết sau.","hs":"- HS thực hành nặn chân dung 3D.\n- HS hoàn thiện, lưu giữ sản phẩm."},{"ten":"4. Vận dụng","gv":"- GV cho HS chia sẻ: em thể hiện gương mặt của ai? Đặc điểm nào nổi bật?\n- GV khen ngợi, dặn HS chuẩn bị cho tiết 3.","hs":"- HS chia sẻ về sản phẩm.\n- HS ghi nhớ nhiệm vụ."}]},
{"lop":2,"mon":"Mĩ thuật","tuan":20,"tiet":20,"bai":"Chủ đề 7: GƯƠNG MẶT THÂN QUEN — Tiết 3: Vận dụng (đắp nổi)","yccd":"1. Năng lực mĩ thuật\n- Củng cố kiến thức, kĩ năng về tạo hình chân dung đã học.\n- Sử dụng tạo hình chân dung để trang trí một sản phẩm theo hình thức đắp nổi.\n- Biết phối hợp màu sắc, chất liệu để sản phẩm sinh động.\n2. Năng lực chung\n- Giải quyết vấn đề và sáng tạo: vận dụng tạo hình chân dung vào trang trí.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ cách làm với bạn.\n3. Phẩm chất\n- Yêu quý người thân; chăm chỉ, kiên trì.","dodung":"- Giáo viên: sản phẩm đắp nổi mẫu; đất nặn; thiết bị trình chiếu.\n- Học sinh: sản phẩm các tiết trước, đất nặn, giấy bìa, bút màu, keo dán.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV kiểm tra sản phẩm tiết 2, khen ngợi, động viên.\n- GV giới thiệu hình thức đắp nổi, dẫn vào bài.","hs":"- HS trưng bày sản phẩm tiết 2.\n- HS lắng nghe, mở bài học."},{"ten":"2. Khám phá — Đắp nổi chân dung","gv":"- GV cho HS quan sát sản phẩm đắp nổi có tạo hình chân dung.\n- GV đặt câu hỏi: Sản phẩm được đắp nổi thế nào? Chân dung được tạo trên nền gì?\n- GV thị phạm cách đắp nổi đơn giản.","hs":"- HS quan sát, trả lời câu hỏi.\n- HS quan sát GV thị phạm, ghi nhớ."},{"ten":"3. Luyện tập — Sáng tạo","gv":"- GV yêu cầu HS dùng tạo hình chân dung để trang trí một sản phẩm theo hình thức đắp nổi.\n- GV quan sát, giúp đỡ; nhắc HS lưu giữ sản phẩm cho tiết sau.","hs":"- HS thực hành đắp nổi tạo hình chân dung.\n- HS lưu giữ sản phẩm."},{"ten":"4. Vận dụng","gv":"- GV cho HS chia sẻ nhanh về sản phẩm đang làm.\n- GV khen ngợi, dặn HS chuẩn bị cho tiết 4.","hs":"- HS chia sẻ về sản phẩm.\n- HS ghi nhớ nhiệm vụ."}]},
{"lop":2,"mon":"Mĩ thuật","tuan":21,"tiet":21,"bai":"Chủ đề 7: GƯƠNG MẶT THÂN QUEN — Tiết 4: Vận dụng (đắp nổi, tiếp theo) và trưng bày","yccd":"1. Năng lực mĩ thuật\n- Hoàn thiện sản phẩm trang trí bằng tạo hình chân dung theo hình thức đắp nổi.\n- Trưng bày, giới thiệu và nêu cảm nhận về sản phẩm của mình và của bạn.\n- Biết đánh giá sản phẩm theo tiêu chí đơn giản.\n2. Năng lực chung\n- Giao tiếp và hợp tác: tự tin giới thiệu sản phẩm, lắng nghe nhận xét.\n3. Phẩm chất\n- Yêu quý người thân; trân trọng sản phẩm do mình và bạn tạo ra.\n4. Tích hợp\n- Năng lực số 3.2 CB1 (Tích hợp và tinh chỉnh nội dung số): HS xem trang trưng bày và nhận ra tên tác giả của từng bức.","dodung":"- Giáo viên: bảng trưng bày; tiêu chí đánh giá; thiết bị trình chiếu.\n- Học sinh: sản phẩm tiết 3, đất nặn, bút màu, keo dán để hoàn thiện.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV kiểm tra sản phẩm tiết 3, khen ngợi, động viên.\n- GV nêu nhiệm vụ tiết học: hoàn thiện và trưng bày sản phẩm.","hs":"- HS trưng bày sản phẩm tiết 3.\n- HS lắng nghe, mở bài học."},{"ten":"2. Khám phá — Hoàn thiện","gv":"- GV gợi ý HS bổ sung chi tiết, màu sắc để sản phẩm đắp nổi thêm sinh động.\n- GV quan sát, giúp đỡ HS hoàn thiện.","hs":"- HS bổ sung chi tiết, hoàn thiện sản phẩm.\n- HS trao đổi với bạn."},{"ten":"3. Luyện tập — Hoàn thiện sản phẩm","gv":"- GV cho HS tiếp tục hoàn thiện sản phẩm đắp nổi chân dung.\n- GV quan sát, hỗ trợ HS gặp khó khăn.","hs":"- HS hoàn thiện sản phẩm đắp nổi.\n- HS chuẩn bị trưng bày."},{"ten":"4. Vận dụng — Trưng bày","gv":"- GV tổ chức trưng bày, chia sẻ: Sản phẩm của em thể hiện gương mặt ai? Em thích sản phẩm nào nhất?\n- GV cùng HS nhận xét, động viên; dặn xem trước Chủ đề 8.","hs":"- HS trưng bày, giới thiệu sản phẩm.\n- HS nhận xét, ghi nhớ nhiệm vụ."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV chụp các bức chân dung đắp nổi từ hướng chếch để thấy rõ độ nổi, rồi ghép thành một trang trưng bày có ghi tên tác giả dưới mỗi ảnh.\n- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 1) HS đoán xem mỗi bức chân dung vẽ ai; bạn được vẽ nghe lời khen thì nói lời cảm ơn.\n⚠ (Miền 4: An toàn) Chỉ chụp sản phẩm, không chụp mặt bạn khi bạn chưa đồng ý; trang trưng bày chỉ mở trong lớp, không gửi ra ngoài.","hs":"- HS xem trang trưng bày và nhận ra tên tác giả của từng bức.\n- HS khen bạn và đáp lại lời khen một cách lịch sự."}]},
{"lop":2,"mon":"Mĩ thuật","tuan":22,"tiet":22,"bai":"Chủ đề 8: BỮA CƠM GIA ĐÌNH — Tiết 1: Quan sát và thể hiện (2D)","yccd":"1. Năng lực mĩ thuật\n- Tìm hiểu hình ảnh thể hiện về bữa cơm gia đình.\n- Tạo được một sản phẩm mĩ thuật thể hiện về chủ đề dạng 2D (vẽ hoặc xé dán).\n- Bước đầu biết sắp xếp hình ảnh có nội dung, có nhân vật.\n2. Năng lực chung\n- Tự chủ và tự học: quan sát, nhớ lại bữa cơm gia đình để thể hiện.\n- Giao tiếp và hợp tác: chia sẻ về bữa cơm gia đình mình.\n3. Phẩm chất\n- Yêu gia đình; trân trọng những bữa cơm sum họp bên người thân.\n4. Tích hợp\n- Năng lực số 1.1 CB1 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS nêu được điểm giống và khác giữa các bữa cơm gia đình qua bộ ảnh.","dodung":"- Giáo viên: tranh ảnh về bữa cơm gia đình; sản phẩm mĩ thuật mẫu; thiết bị trình chiếu.\n- Học sinh: SGK Mĩ thuật 2, Vở bài tập Mĩ thuật 2, bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, hồ dán.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS hát/nghe một bài hát về gia đình, hỏi: Bữa cơm gia đình em thường có những ai?\n- GV nhận xét, giới thiệu chủ đề.","hs":"- HS hát/nghe, trả lời câu hỏi.\n- HS lắng nghe, mở bài học."},{"ten":"2. Khám phá — Hình ảnh bữa cơm","gv":"- GV cho HS quan sát tranh ảnh về bữa cơm gia đình và hình trong SGK.\n- GV đặt câu hỏi: Bữa cơm có những ai? Mọi người làm gì? Không khí bữa cơm thế nào?\n- GV chốt về nội dung, hình ảnh, không khí bữa cơm gia đình.","hs":"- HS quan sát, trả lời câu hỏi.\n- HS nhận biết cách thể hiện hình ảnh bữa cơm.\n- HS lắng nghe, ghi nhớ."},{"ten":"3. Luyện tập — Sáng tạo (2D)","gv":"- GV hướng dẫn HS tham khảo cách thể hiện trong SGK.\n- GV yêu cầu HS vẽ hoặc xé dán một sản phẩm về bữa cơm gia đình dạng 2D.\n- GV quan sát, giúp đỡ; nhắc HS lưu giữ sản phẩm cho tiết sau.","hs":"- HS tham khảo, tiếp thu cách làm.\n- HS thực hành thể hiện chủ đề dạng 2D.\n- HS lưu giữ sản phẩm."},{"ten":"4. Vận dụng","gv":"- GV cho HS chia sẻ: bức tranh của em thể hiện bữa cơm với ai?\n- GV khen ngợi, dặn HS chuẩn bị cho tiết 2.","hs":"- HS chia sẻ về sản phẩm.\n- HS ghi nhớ nhiệm vụ."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV chiếu bộ ảnh bữa cơm của các gia đình ở nhiều vùng miền: mâm cơm đồng bằng, mâm cơm miền núi, mâm cơm ngày Tết; HS thấy được sự khác nhau về món ăn, chỗ ngồi và cách bày mâm.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) HS kể lại bữa cơm nhà mình: ai ngồi cạnh ai, mâm cơm đặt ở đâu, thường có món gì.\n⚠ (Miền 4: An toàn) GV dùng ảnh tư liệu đã chuẩn bị; HS không mang ảnh chụp gia đình mình đến chiếu lên màn hình vì đó là chuyện riêng của mỗi nhà.","hs":"- HS nêu được điểm giống và khác giữa các bữa cơm gia đình qua bộ ảnh.\n- HS kể được bữa cơm nhà mình để lấy ý cho bài vẽ."}]},
{"lop":2,"mon":"Mĩ thuật","tuan":23,"tiet":23,"bai":"Chủ đề 8: BỮA CƠM GIA ĐÌNH — Tiết 2: Thể hiện (3D)","yccd":"1. Năng lực mĩ thuật\n- Tìm hiểu cách thể hiện hình ảnh về người thân qua một số sản phẩm mĩ thuật.\n- Thể hiện được một sản phẩm mĩ thuật về chủ đề ở dạng 3D (nặn, tạo khối).\n- Biết tạo hình nhân vật, đồ vật trong bữa cơm bằng chất liệu 3D.\n2. Năng lực chung\n- Giải quyết vấn đề và sáng tạo: tạo hình nhân vật, đồ vật 3D theo chủ đề.\n- Giao tiếp và hợp tác: phối hợp với bạn khi tạo sản phẩm.\n3. Phẩm chất\n- Yêu gia đình; chăm chỉ, kiên trì hoàn thành sản phẩm.","dodung":"- Giáo viên: sản phẩm 3D mẫu về chủ đề; đất nặn; thiết bị trình chiếu.\n- Học sinh: sản phẩm tiết 1, đất nặn, vật liệu tái sử dụng, bút màu.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV kiểm tra sản phẩm tiết 1, khen ngợi, động viên.\n- GV cho HS xem một sản phẩm 3D về bữa cơm, dẫn vào bài.","hs":"- HS trưng bày sản phẩm tiết 1.\n- HS quan sát, lắng nghe."},{"ten":"2. Khám phá — Tạo hình 3D","gv":"- GV cho HS quan sát sản phẩm 3D về người thân, bữa cơm.\n- GV đặt câu hỏi: Sản phẩm thể hiện những gì? Nhân vật, đồ vật được nặn thế nào?\n- GV chốt cách tạo hình 3D theo chủ đề.","hs":"- HS quan sát, trả lời câu hỏi.\n- HS nhận biết cách tạo hình 3D.\n- HS lắng nghe, ghi nhớ."},{"ten":"3. Luyện tập — Sáng tạo (3D)","gv":"- GV yêu cầu HS nặn, tạo khối một sản phẩm 3D về bữa cơm gia đình (nhân vật, mâm cơm, đồ vật...).\n- GV quan sát, giúp đỡ; nhắc HS lưu giữ sản phẩm cho tiết sau.","hs":"- HS thực hành nặn sản phẩm 3D.\n- HS hoàn thiện, lưu giữ sản phẩm."},{"ten":"4. Vận dụng","gv":"- GV cho HS chia sẻ: sản phẩm 3D của em thể hiện điều gì?\n- GV khen ngợi, dặn HS chuẩn bị cho tiết 3.","hs":"- HS chia sẻ về sản phẩm.\n- HS ghi nhớ nhiệm vụ."}]},
{"lop":2,"mon":"Mĩ thuật","tuan":24,"tiet":24,"bai":"Chủ đề 8: BỮA CƠM GIA ĐÌNH — Tiết 3: Vận dụng (tạo dáng lọ hoa)","yccd":"1. Năng lực mĩ thuật\n- Củng cố kiến thức, kĩ năng đã học về chủ đề gia đình.\n- Tạo dáng và trang trí một lọ hoa để làm đẹp bữa cơm, không gian gia đình.\n- Biết kết hợp tạo dáng và trang trí trên sản phẩm.\n2. Năng lực chung\n- Giải quyết vấn đề và sáng tạo: tạo dáng, trang trí lọ hoa theo ý tưởng.\n- Giao tiếp và hợp tác: trao đổi cách làm với bạn.\n3. Phẩm chất\n- Yêu gia đình; biết làm đẹp không gian sống.","dodung":"- Giáo viên: lọ hoa mẫu; vật liệu tái sử dụng (chai, lọ nhựa); thiết bị trình chiếu.\n- Học sinh: sản phẩm các tiết trước, chai/lọ nhựa, giấy màu, đất nặn, màu vẽ, kéo, keo dán.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV kiểm tra sản phẩm tiết 2, khen ngợi, động viên.\n- GV cho HS xem một lọ hoa trang trí đẹp, dẫn vào bài.","hs":"- HS trưng bày sản phẩm tiết 2.\n- HS quan sát, lắng nghe."},{"ten":"2. Khám phá — Tạo dáng lọ hoa","gv":"- GV cho HS quan sát lọ hoa mẫu và hình trong SGK.\n- GV đặt câu hỏi: Lọ hoa có dáng thế nào? Được trang trí bằng họa tiết gì? Làm từ vật liệu nào?\n- GV thị phạm cách tạo dáng, trang trí lọ hoa từ vật liệu tái sử dụng.","hs":"- HS quan sát, trả lời câu hỏi.\n- HS quan sát GV thị phạm, ghi nhớ."},{"ten":"3. Luyện tập — Sáng tạo","gv":"- GV yêu cầu HS tạo dáng và trang trí một lọ hoa từ vật liệu tái sử dụng.\n- GV quan sát, giúp đỡ; nhắc HS lưu giữ sản phẩm cho tiết sau.","hs":"- HS thực hành tạo dáng và trang trí lọ hoa.\n- HS lưu giữ sản phẩm."},{"ten":"4. Vận dụng","gv":"- GV cho HS chia sẻ nhanh về lọ hoa đang làm.\n- GV khen ngợi, dặn HS chuẩn bị cho tiết 4.","hs":"- HS chia sẻ về sản phẩm.\n- HS ghi nhớ nhiệm vụ."}]},
{"lop":2,"mon":"Mĩ thuật","tuan":25,"tiet":25,"bai":"Chủ đề 8: BỮA CƠM GIA ĐÌNH — Tiết 4: Vận dụng (hoàn thiện lọ hoa) và trưng bày","yccd":"1. Năng lực mĩ thuật\n- Hoàn thiện lọ hoa đã tạo dáng và trang trí ở tiết trước.\n- Trưng bày, giới thiệu và nêu cảm nhận về sản phẩm của mình và của bạn.\n- Biết đánh giá sản phẩm theo tiêu chí đơn giản.\n2. Năng lực chung\n- Giao tiếp và hợp tác: tự tin giới thiệu sản phẩm, lắng nghe nhận xét.\n3. Phẩm chất\n- Yêu gia đình; trân trọng sản phẩm và biết làm đẹp không gian sống.\n4. Tích hợp\n- Năng lực số 3.2 CB1 (Tích hợp và tinh chỉnh nội dung số): HS nhận ra ảnh chụp sản phẩm đẹp hơn khi nền gọn và đủ sáng.","dodung":"- Giáo viên: bảng trưng bày; tiêu chí đánh giá; thiết bị trình chiếu.\n- Học sinh: sản phẩm tiết 3, giấy màu, màu vẽ, keo dán để hoàn thiện.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV kiểm tra sản phẩm tiết 3, khen ngợi, động viên.\n- GV nêu nhiệm vụ: hoàn thiện và trưng bày lọ hoa.","hs":"- HS trưng bày sản phẩm tiết 3.\n- HS lắng nghe, mở bài học."},{"ten":"2. Khám phá — Hoàn thiện","gv":"- GV gợi ý HS bổ sung họa tiết, màu sắc để lọ hoa thêm đẹp.\n- GV quan sát, giúp đỡ HS hoàn thiện.","hs":"- HS bổ sung chi tiết, hoàn thiện lọ hoa.\n- HS trao đổi với bạn."},{"ten":"3. Luyện tập — Hoàn thiện sản phẩm","gv":"- GV cho HS tiếp tục hoàn thiện và cắm hoa (hoa giấy, hoa khô) vào lọ.\n- GV quan sát, hỗ trợ HS.","hs":"- HS hoàn thiện lọ hoa và cắm hoa trang trí.\n- HS chuẩn bị trưng bày."},{"ten":"4. Vận dụng — Trưng bày","gv":"- GV tổ chức trưng bày, chia sẻ: Lọ hoa của em làm từ vật liệu gì? Em thích sản phẩm nào nhất?\n- GV cùng HS nhận xét, động viên; dặn xem trước Chủ đề 9.","hs":"- HS trưng bày, giới thiệu lọ hoa.\n- HS nhận xét, ghi nhớ nhiệm vụ."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV xếp các lọ hoa của HS lên một mặt bàn có phông nền sạch, chụp cả nhóm rồi chụp riêng từng chiếc; HS thấy cùng một sản phẩm nhưng đặt nền gọn, đủ sáng thì ảnh đẹp hơn hẳn.\n- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 1) HS nói cho cả lớp nghe mình đã tận dụng vỏ chai, vỏ hộp gì để làm lọ hoa.\n⚠ (Miền 4: An toàn) Không dùng chai lọ thuỷ tinh vỡ hay sắc cạnh; đặt sản phẩm chắc chắn rồi mới chụp; ảnh sản phẩm chỉ chiếu trong lớp và cho cha mẹ xem.","hs":"- HS nhận ra ảnh chụp sản phẩm đẹp hơn khi nền gọn và đủ sáng.\n- HS giới thiệu được vật liệu tái sử dụng mình đã dùng."}]},
{"lop":2,"mon":"Mĩ thuật","tuan":26,"tiet":26,"bai":"Chủ đề 9: THẦY CÔ CỦA EM — Tiết 1: Quan sát và thể hiện (theo liên tưởng)","yccd":"1. Năng lực mĩ thuật\n- Tìm hiểu, mô tả được hình ảnh liên quan đến chủ đề thầy cô.\n- Thể hiện được về chủ đề từ hình ảnh đã liên tưởng (vẽ hoặc xé dán).\n- Bước đầu biết chọn hình ảnh, hoạt động tiêu biểu về thầy cô.\n2. Năng lực chung\n- Tự chủ và tự học: nhớ lại, liên tưởng hình ảnh thầy cô để thể hiện.\n- Giao tiếp và hợp tác: chia sẻ tình cảm với thầy cô.\n3. Phẩm chất\n- Kính trọng, biết ơn thầy cô giáo; chăm ngoan, lễ phép.\n4. Tích hợp\n- Năng lực số 1.1 CB1 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS kể được những việc thầy cô làm hằng ngày sau khi xem phim, ảnh.","dodung":"- Giáo viên: tranh ảnh về thầy cô và hoạt động dạy học; sản phẩm mĩ thuật mẫu; thiết bị trình chiếu.\n- Học sinh: SGK Mĩ thuật 2, Vở bài tập Mĩ thuật 2, bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, hồ dán.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS hát/nghe một bài hát về thầy cô, hỏi: Em nhớ nhất hình ảnh nào của thầy cô?\n- GV nhận xét, giới thiệu chủ đề.","hs":"- HS hát/nghe, trả lời câu hỏi.\n- HS lắng nghe, mở bài học."},{"ten":"2. Khám phá — Hình ảnh thầy cô","gv":"- GV cho HS quan sát tranh ảnh về thầy cô và hình trong SGK.\n- GV đặt câu hỏi: Thầy cô đang làm gì? Hình ảnh nào gợi cho em nhiều cảm xúc? Em muốn thể hiện thầy cô trong hoạt động nào?\n- GV chốt về cách chọn hình ảnh, hoạt động tiêu biểu.","hs":"- HS quan sát, trả lời câu hỏi.\n- HS liên tưởng, chọn hình ảnh về thầy cô.\n- HS lắng nghe, ghi nhớ."},{"ten":"3. Luyện tập — Sáng tạo","gv":"- GV hướng dẫn HS tham khảo cách thể hiện trong SGK.\n- GV yêu cầu HS vẽ hoặc xé dán một sản phẩm về chủ đề thầy cô từ hình ảnh đã liên tưởng.\n- GV quan sát, giúp đỡ; nhắc HS lưu giữ sản phẩm cho tiết sau.","hs":"- HS tham khảo, tiếp thu cách làm.\n- HS thực hành thể hiện chủ đề thầy cô.\n- HS lưu giữ sản phẩm."},{"ten":"4. Vận dụng","gv":"- GV cho HS chia sẻ: em thể hiện thầy cô trong hoạt động nào?\n- GV khen ngợi, dặn HS chuẩn bị cho tiết 2.","hs":"- HS chia sẻ về sản phẩm.\n- HS ghi nhớ nhiệm vụ."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV chiếu bộ ảnh và đoạn phim ngắn về công việc hằng ngày của thầy cô: soạn bài, chấm bài, hướng dẫn HS tập thể dục, tưới cây cùng HS; HS nhận ra nhiều việc thầy cô làm mà lúc học các em không nhìn thấy.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) HS chọn một việc trong phim để đưa vào tranh của mình và tả lại việc đó bằng lời.\n⚠ (Miền 4: An toàn) Phim, ảnh về thầy cô do nhà trường và GV cung cấp; HS không tự quay, chụp thầy cô hay các bạn khi chưa xin phép.","hs":"- HS kể được những việc thầy cô làm hằng ngày sau khi xem phim, ảnh.\n- HS chọn được một việc để thể hiện trong tranh của mình."}]},
{"lop":2,"mon":"Mĩ thuật","tuan":27,"tiet":27,"bai":"Chủ đề 9: THẦY CÔ CỦA EM — Tiết 2: Thể hiện (theo cách yêu thích)","yccd":"1. Năng lực mĩ thuật\n- Tìm hiểu về chủ đề thông qua một số bức tranh.\n- Thể hiện được một sản phẩm mĩ thuật về chủ đề theo cách mình yêu thích.\n- Biết chọn hình thức, chất liệu phù hợp để thể hiện.\n2. Năng lực chung\n- Giải quyết vấn đề và sáng tạo: chọn cách thể hiện riêng về chủ đề thầy cô.\n- Giao tiếp và hợp tác: chia sẻ, trao đổi với bạn.\n3. Phẩm chất\n- Kính trọng, biết ơn thầy cô; chăm chỉ, sáng tạo.","dodung":"- Giáo viên: một số bức tranh về chủ đề thầy cô; sản phẩm mẫu; thiết bị trình chiếu.\n- Học sinh: sản phẩm tiết 1, màu vẽ, giấy vẽ, giấy màu, đất nặn, kéo, hồ dán.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV kiểm tra sản phẩm tiết 1, khen ngợi, động viên.\n- GV cho HS xem một số bức tranh về thầy cô, dẫn vào bài.","hs":"- HS trưng bày sản phẩm tiết 1.\n- HS quan sát, lắng nghe."},{"ten":"2. Khám phá — Xem tranh về thầy cô","gv":"- GV cho HS quan sát một số bức tranh về chủ đề thầy cô.\n- GV đặt câu hỏi: Tranh thể hiện hoạt động gì? Cách vẽ, màu sắc thế nào? Em thích cách thể hiện nào?\n- GV chốt về các cách thể hiện chủ đề.","hs":"- HS quan sát, trả lời câu hỏi.\n- HS nhận biết các cách thể hiện chủ đề.\n- HS lắng nghe, ghi nhớ."},{"ten":"3. Luyện tập — Sáng tạo","gv":"- GV yêu cầu HS thể hiện một sản phẩm về chủ đề thầy cô theo cách mình yêu thích (vẽ, xé dán, nặn...).\n- GV quan sát, giúp đỡ; nhắc HS lưu giữ sản phẩm cho tiết sau.","hs":"- HS thực hành thể hiện sản phẩm theo cách yêu thích.\n- HS hoàn thiện, lưu giữ sản phẩm."},{"ten":"4. Vận dụng","gv":"- GV cho HS chia sẻ: em chọn cách thể hiện nào? Vì sao?\n- GV khen ngợi, dặn HS chuẩn bị cho tiết 3.","hs":"- HS chia sẻ về sản phẩm.\n- HS ghi nhớ nhiệm vụ."}]},
{"lop":2,"mon":"Mĩ thuật","tuan":28,"tiet":28,"bai":"Chủ đề 9: THẦY CÔ CỦA EM — Tiết 3: Thảo luận và vận dụng (làm món quà lưu niệm)","yccd":"1. Năng lực mĩ thuật\n- Củng cố kiến thức, kĩ năng đã học về chủ đề thầy cô.\n- Làm được một món quà lưu niệm (thiệp, hoa giấy, khung ảnh nhỏ...) tặng thầy cô.\n- Nêu được cảm nhận về sản phẩm của mình và của bạn.\n2. Năng lực chung\n- Giải quyết vấn đề và sáng tạo: lựa chọn hình thức món quà phù hợp.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ cách làm với bạn.\n3. Phẩm chất\n- Kính trọng, biết ơn thầy cô; biết thể hiện tình cảm qua món quà tự làm.\n4. Tích hợp\n- Năng lực số 1.1 CB1 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS làm được món quà theo phim hướng dẫn và biết tua chậm lại bước khó.","dodung":"- Giáo viên: một số món quà lưu niệm mẫu; vật liệu làm thiệp, hoa giấy; thiết bị trình chiếu.\n- Học sinh: sản phẩm các tiết trước, giấy màu, bút màu, kéo, keo dán, vật liệu trang trí.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV kiểm tra sản phẩm tiết 2, khen ngợi, động viên.\n- GV giới thiệu ý nghĩa món quà tự làm tặng thầy cô, dẫn vào bài.","hs":"- HS trưng bày sản phẩm tiết 2.\n- HS lắng nghe, mở bài học."},{"ten":"2. Khám phá — Thảo luận và tìm hiểu quà lưu niệm","gv":"- GV tổ chức cho HS thảo luận: Em muốn làm món quà gì tặng thầy cô? Cần vật liệu nào?\n- GV cho HS quan sát một số món quà lưu niệm mẫu, chốt cách làm.","hs":"- HS thảo luận, chọn món quà.\n- HS quan sát mẫu, ghi nhớ cách làm."},{"ten":"3. Luyện tập — Sáng tạo","gv":"- GV yêu cầu HS làm một món quà lưu niệm (thiệp, hoa giấy...) để tặng thầy cô.\n- GV quan sát, giúp đỡ HS hoàn thiện sản phẩm.","hs":"- HS thực hành làm món quà lưu niệm.\n- HS hoàn thiện sản phẩm."},{"ten":"4. Vận dụng — Trưng bày","gv":"- GV tổ chức trưng bày, chia sẻ: Em làm món quà gì? Muốn tặng thầy cô nào?\n- GV cùng HS nhận xét, động viên; dặn chuẩn bị cho tiết sau.","hs":"- HS trưng bày, giới thiệu món quà.\n- HS nhận xét, ghi nhớ nhiệm vụ."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV chiếu đoạn phim hướng dẫn gấp hoa giấy, làm thiếp nổi, dừng lại và tua chậm ở bước khó để HS xem lại vài lần trước khi tự làm; xem GV làm mẫu một lần thì bạn ngồi xa không kịp nhìn rõ.\n- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 1) HS làm theo từng bước; bạn nào làm được trước thì quay sang giúp bạn bên cạnh.\n⚠ (Miền 4: An toàn) Cẩn thận với kéo và keo dán khi làm theo phim; chỉ mở đúng đoạn phim GV đã tải sẵn, không bấm sang phim khác đang gợi ý bên cạnh.","hs":"- HS làm được món quà theo phim hướng dẫn và biết tua chậm lại bước khó.\n- HS giúp bạn bên cạnh hoàn thành sản phẩm."}]},
{"lop":2,"mon":"Mĩ thuật","tuan":29,"tiet":29,"bai":"Chủ đề 9: THẦY CÔ CỦA EM — Tiết 4: Vận dụng (hoàn thiện quà lưu niệm) và trưng bày","yccd":"1. Năng lực mĩ thuật\n- Hoàn thiện món quà lưu niệm tặng thầy cô.\n- Trưng bày, giới thiệu và nêu cảm nhận về sản phẩm của mình và của bạn.\n- Biết đánh giá sản phẩm theo tiêu chí đơn giản.\n2. Năng lực chung\n- Giao tiếp và hợp tác: tự tin giới thiệu sản phẩm, lắng nghe nhận xét.\n3. Phẩm chất\n- Kính trọng, biết ơn thầy cô; trân trọng sản phẩm tự làm.\n4. Tích hợp\n- Năng lực số 3.2 CB1 (Tích hợp và tinh chỉnh nội dung số): HS viết và đọc được lời chúc lễ phép, chân thành.","dodung":"- Giáo viên: bảng trưng bày; tiêu chí đánh giá; thiết bị trình chiếu.\n- Học sinh: sản phẩm tiết 3, giấy màu, bút màu, keo dán để hoàn thiện.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV kiểm tra sản phẩm tiết 3, khen ngợi, động viên.\n- GV nêu nhiệm vụ: hoàn thiện và trưng bày món quà.","hs":"- HS trưng bày sản phẩm tiết 3.\n- HS lắng nghe, mở bài học."},{"ten":"2. Khám phá — Hoàn thiện","gv":"- GV gợi ý HS bổ sung họa tiết, lời chúc để món quà thêm ý nghĩa.\n- GV quan sát, giúp đỡ HS hoàn thiện.","hs":"- HS bổ sung chi tiết, hoàn thiện món quà.\n- HS trao đổi với bạn."},{"ten":"3. Luyện tập — Hoàn thiện sản phẩm","gv":"- GV cho HS tiếp tục hoàn thiện món quà lưu niệm.\n- GV quan sát, hỗ trợ HS.","hs":"- HS hoàn thiện món quà.\n- HS chuẩn bị trưng bày."},{"ten":"4. Vận dụng — Trưng bày","gv":"- GV tổ chức trưng bày, chia sẻ: Em thích món quà nào nhất? Vì sao?\n- GV cùng HS nhận xét, động viên; dặn xem trước Chủ đề 10.","hs":"- HS trưng bày, giới thiệu món quà.\n- HS nhận xét, ghi nhớ nhiệm vụ."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV chụp món quà của HS kèm tấm thiếp ghi lời chúc, ghép thành một trang trưng bày của lớp để tặng thầy cô xem.\n- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 1) HS đọc to lời chúc của mình, cả lớp góp ý để lời chúc chân thành và lễ phép hơn.\n⚠ (Miền 4: An toàn) Trang trưng bày chỉ gửi tới thầy cô trong trường, không đăng lên mạng; lời chúc ghi tên người nhận nhưng không ghi số điện thoại, địa chỉ của ai.","hs":"- HS viết và đọc được lời chúc lễ phép, chân thành.\n- HS xem trang trưng bày quà của cả lớp và nhận xét tích cực."}]},
{"lop":2,"mon":"Mĩ thuật","tuan":30,"tiet":30,"bai":"Chủ đề 10: ĐỒ CHƠI TỪ TẠO HÌNH CON VẬT — Tiết 1: Quan sát và thể hiện (chiếc mặt nạ)","yccd":"1. Năng lực mĩ thuật\n- Tìm hiểu, mô tả một số đồ chơi dân gian truyền thống Việt Nam.\n- Thể hiện được về chiếc mặt nạ con vật (vẽ, xé dán hoặc tạo hình trên bìa).\n- Bước đầu biết tạo dáng, trang trí mặt nạ con vật.\n2. Năng lực chung\n- Tự chủ và tự học: quan sát, lựa chọn con vật để tạo mặt nạ.\n- Giao tiếp và hợp tác: chia sẻ về đồ chơi dân gian.\n3. Phẩm chất\n- Yêu quý đồ chơi dân gian truyền thống; tự hào về nét đẹp văn hóa dân tộc.\n4. Tích hợp\n- Năng lực số 1.1 CB1 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS kể được một số đồ chơi dân gian và vật liệu làm ra chúng.","dodung":"- Giáo viên: một số đồ chơi dân gian (mặt nạ, đèn ông sao...); mặt nạ con vật mẫu; thiết bị trình chiếu.\n- Học sinh: SGK Mĩ thuật 2, Vở bài tập Mĩ thuật 2, giấy bìa, màu vẽ, giấy màu, kéo, keo dán, dây.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS xem một số đồ chơi dân gian, hỏi: Em biết những đồ chơi dân gian nào?\n- GV nhận xét, giới thiệu chủ đề.","hs":"- HS quan sát, kể tên đồ chơi dân gian.\n- HS lắng nghe, mở bài học."},{"ten":"2. Khám phá — Đồ chơi dân gian và mặt nạ","gv":"- GV cho HS quan sát đồ chơi dân gian, mặt nạ con vật và hình trong SGK.\n- GV đặt câu hỏi: Mặt nạ có hình con vật gì? Được trang trí thế nào? Làm từ vật liệu nào?\n- GV chốt về đặc điểm, cách làm mặt nạ con vật.","hs":"- HS quan sát, trả lời câu hỏi.\n- HS nhận biết cách tạo dáng, trang trí mặt nạ.\n- HS lắng nghe, ghi nhớ."},{"ten":"3. Luyện tập — Sáng tạo","gv":"- GV hướng dẫn HS tham khảo cách làm mặt nạ trong SGK.\n- GV yêu cầu HS thể hiện một chiếc mặt nạ con vật yêu thích (vẽ, xé dán, tạo hình trên bìa).\n- GV quan sát, giúp đỡ; nhắc HS lưu giữ sản phẩm cho tiết sau.","hs":"- HS tham khảo, tiếp thu cách làm.\n- HS thực hành làm mặt nạ con vật.\n- HS lưu giữ sản phẩm."},{"ten":"4. Vận dụng","gv":"- GV cho HS chia sẻ: em làm mặt nạ con vật gì? Trang trí thế nào?\n- GV khen ngợi, dặn HS chuẩn bị cho tiết 2.","hs":"- HS chia sẻ về sản phẩm.\n- HS ghi nhớ nhiệm vụ."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV chiếu phim tư liệu về đồ chơi dân gian Việt Nam: mặt nạ giấy bồi, tò he, đèn ông sao, con giống bột; phim quay cận cảnh bàn tay người thợ nên HS thấy rõ từng thao tác nặn, phết màu.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) HS gọi tên các đồ chơi trong phim và nói món nào mình đã từng chơi.\n⚠ (Miền 4: An toàn) GV mở đoạn phim đã tải sẵn; HS xem để hiểu công sức của người thợ làm ra một món đồ chơi, không đòi mua đồ chơi theo quảng cáo chen trong các phim trên mạng.","hs":"- HS kể được một số đồ chơi dân gian và vật liệu làm ra chúng.\n- HS nêu được cảm nhận về công sức của người thợ thủ công."}]},
{"lop":2,"mon":"Mĩ thuật","tuan":31,"tiet":31,"bai":"Chủ đề 10: ĐỒ CHƠI TỪ TẠO HÌNH CON VẬT — Tiết 2: Thể hiện (đồ chơi từ vật liệu tái sử dụng)","yccd":"1. Năng lực mĩ thuật\n- Tìm hiểu đồ chơi làm từ vật liệu tái sử dụng.\n- Thể hiện được một món đồ chơi con vật từ vật liệu tái sử dụng.\n- Biết kết hợp tạo dáng và trang trí đồ chơi.\n2. Năng lực chung\n- Giải quyết vấn đề và sáng tạo: tận dụng vật liệu tái sử dụng để tạo đồ chơi.\n- Giao tiếp và hợp tác: phối hợp với bạn khi làm sản phẩm.\n3. Phẩm chất\n- Yêu thiên nhiên, bảo vệ môi trường; tiết kiệm, tận dụng vật liệu tái sử dụng.\n4. Tích hợp\n- Năng lực số 1.1 CB1 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS làm được đồ chơi con vật từ vật liệu tái sử dụng theo phim hướng dẫn.","dodung":"- Giáo viên: đồ chơi con vật làm từ vật liệu tái sử dụng (mẫu); thiết bị trình chiếu.\n- Học sinh: sản phẩm tiết 1, chai/lọ nhựa, hộp giấy, nắp chai, vải vụn, màu vẽ, kéo, keo dán.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV kiểm tra sản phẩm tiết 1, khen ngợi, động viên.\n- GV cho HS xem đồ chơi con vật từ vật liệu tái sử dụng, dẫn vào bài.","hs":"- HS trưng bày sản phẩm tiết 1.\n- HS quan sát, lắng nghe."},{"ten":"2. Khám phá — Đồ chơi từ vật liệu tái sử dụng","gv":"- GV cho HS quan sát đồ chơi con vật làm từ chai lọ, hộp giấy, nắp chai...\n- GV đặt câu hỏi: Đồ chơi làm từ vật liệu gì? Con vật được tạo thế nào? Vì sao nên tái sử dụng vật liệu?\n- GV chốt về cách làm và ý nghĩa bảo vệ môi trường.","hs":"- HS quan sát, trả lời câu hỏi.\n- HS nhận biết cách làm đồ chơi tái chế.\n- HS lắng nghe, ghi nhớ."},{"ten":"3. Luyện tập — Sáng tạo","gv":"- GV yêu cầu HS thể hiện một món đồ chơi con vật từ vật liệu tái sử dụng.\n- GV quan sát, giúp đỡ; nhắc HS lưu giữ sản phẩm cho tiết sau.","hs":"- HS thực hành làm đồ chơi con vật từ vật liệu tái sử dụng.\n- HS hoàn thiện, lưu giữ sản phẩm."},{"ten":"4. Vận dụng","gv":"- GV cho HS chia sẻ: em làm con vật gì? Từ vật liệu nào?\n- GV khen ngợi, dặn HS chuẩn bị cho tiết 3.","hs":"- HS chia sẻ về sản phẩm.\n- HS ghi nhớ nhiệm vụ."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV chiếu phim hướng dẫn biến vỏ chai, hộp giấy, nắp chai thành con vật; dừng ở mỗi bước để HS làm theo và tua lại chỗ nào cả lớp chưa kịp.\n- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 1) HS trong nhóm cùng bàn xem nhóm mình làm con vật gì, ai lo phần thân, ai lo phần đầu.\n⚠ (Miền 4: An toàn) Vỏ chai, vỏ hộp phải rửa sạch và để khô trước khi dùng; cẩn thận khi dùng kéo cắt nhựa; chỉ mở đúng đoạn phim GV chỉ định.","hs":"- HS làm được đồ chơi con vật từ vật liệu tái sử dụng theo phim hướng dẫn.\n- HS phân công và làm việc được cùng bạn trong nhóm."}]},
{"lop":2,"mon":"Mĩ thuật","tuan":32,"tiet":32,"bai":"Chủ đề 10: ĐỒ CHƠI TỪ TẠO HÌNH CON VẬT — Tiết 3: Thảo luận và vận dụng (làm ống đựng bút)","yccd":"1. Năng lực mĩ thuật\n- Củng cố kiến thức, kĩ năng đã học về tạo hình con vật.\n- Làm được một ống đựng bút từ vật liệu tái sử dụng, trang trí bằng tạo hình con vật.\n- Biết kết hợp công năng và trang trí trên sản phẩm.\n2. Năng lực chung\n- Giải quyết vấn đề và sáng tạo: tạo sản phẩm vừa đẹp vừa có ích.\n- Giao tiếp và hợp tác: trao đổi cách làm với bạn.\n3. Phẩm chất\n- Bảo vệ môi trường; chăm chỉ, ngăn nắp, biết làm đồ dùng học tập cho mình.","dodung":"- Giáo viên: ống đựng bút mẫu làm từ vật liệu tái sử dụng; thiết bị trình chiếu.\n- Học sinh: sản phẩm các tiết trước, lon/hộp giấy, chai nhựa, giấy màu, màu vẽ, kéo, keo dán.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV kiểm tra sản phẩm tiết 2, khen ngợi, động viên.\n- GV cho HS xem một ống đựng bút trang trí con vật, dẫn vào bài.","hs":"- HS trưng bày sản phẩm tiết 2.\n- HS quan sát, lắng nghe."},{"ten":"2. Khám phá — Thảo luận về ống đựng bút","gv":"- GV tổ chức cho HS thảo luận: Em sẽ làm ống đựng bút hình con vật gì? Từ vật liệu nào?\n- GV cho HS quan sát ống đựng bút mẫu, chốt cách làm.","hs":"- HS thảo luận, chọn con vật và vật liệu.\n- HS quan sát mẫu, ghi nhớ cách làm."},{"ten":"3. Luyện tập — Sáng tạo","gv":"- GV yêu cầu HS làm một ống đựng bút từ vật liệu tái sử dụng, trang trí bằng tạo hình con vật.\n- GV quan sát, giúp đỡ; nhắc HS lưu giữ sản phẩm cho tiết sau.","hs":"- HS thực hành làm ống đựng bút.\n- HS hoàn thiện, lưu giữ sản phẩm."},{"ten":"4. Vận dụng","gv":"- GV cho HS chia sẻ nhanh về ống đựng bút đang làm.\n- GV khen ngợi, dặn HS chuẩn bị cho tiết 4.","hs":"- HS chia sẻ về sản phẩm.\n- HS ghi nhớ nhiệm vụ."}]},
{"lop":2,"mon":"Mĩ thuật","tuan":33,"tiet":33,"bai":"Chủ đề 10: ĐỒ CHƠI TỪ TẠO HÌNH CON VẬT — Tiết 4: Vận dụng (hoàn thiện) và trưng bày","yccd":"1. Năng lực mĩ thuật\n- Hoàn thiện ống đựng bút trang trí tạo hình con vật.\n- Trưng bày, giới thiệu và nêu cảm nhận về sản phẩm của mình và của bạn.\n- Biết đánh giá sản phẩm theo tiêu chí đơn giản.\n2. Năng lực chung\n- Giao tiếp và hợp tác: tự tin giới thiệu sản phẩm, lắng nghe nhận xét.\n3. Phẩm chất\n- Bảo vệ môi trường; trân trọng sản phẩm tự làm và biết sử dụng vào học tập.\n4. Tích hợp\n- Năng lực số 3.2 CB1 (Tích hợp và tinh chỉnh nội dung số): HS xem lại phim góc trưng bày và nhận ra sản phẩm của mình.","dodung":"- Giáo viên: bảng trưng bày; tiêu chí đánh giá; thiết bị trình chiếu.\n- Học sinh: sản phẩm tiết 3, giấy màu, màu vẽ, keo dán để hoàn thiện.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV kiểm tra sản phẩm tiết 3, khen ngợi, động viên.\n- GV nêu nhiệm vụ: hoàn thiện và trưng bày ống đựng bút.","hs":"- HS trưng bày sản phẩm tiết 3.\n- HS lắng nghe, mở bài học."},{"ten":"2. Khám phá — Hoàn thiện","gv":"- GV gợi ý HS bổ sung chi tiết, màu sắc để ống đựng bút thêm sinh động.\n- GV quan sát, giúp đỡ HS hoàn thiện.","hs":"- HS bổ sung chi tiết, hoàn thiện sản phẩm.\n- HS trao đổi với bạn."},{"ten":"3. Luyện tập — Hoàn thiện sản phẩm","gv":"- GV cho HS tiếp tục hoàn thiện ống đựng bút.\n- GV quan sát, hỗ trợ HS.","hs":"- HS hoàn thiện sản phẩm.\n- HS chuẩn bị trưng bày."},{"ten":"4. Vận dụng — Trưng bày","gv":"- GV tổ chức trưng bày, chia sẻ: Ống đựng bút của em hình con vật gì? Em thích sản phẩm nào nhất?\n- GV cùng HS nhận xét, động viên; dặn chuẩn bị kiểm tra cuối năm.","hs":"- HS trưng bày, giới thiệu sản phẩm.\n- HS nhận xét, ghi nhớ nhiệm vụ."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV bày các đồ chơi của lớp thành một góc trưng bày rồi quay một đoạn phim ngắn đi vòng quanh góc ấy để cả lớp xem lại như đi hội chợ đồ chơi.\n- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 1) HS lần lượt cầm sản phẩm giới thiệu trước lớp: đây là con vật gì, làm từ vật liệu gì, chơi ra sao.\n⚠ (Miền 4: An toàn) Đoạn phim chỉ quay sản phẩm và bàn tay, không quay cận mặt bạn nào khi bạn chưa đồng ý; phim giữ trong máy của lớp.","hs":"- HS xem lại phim góc trưng bày và nhận ra sản phẩm của mình.\n- HS giới thiệu được sản phẩm của mình trước lớp."}]},
{"lop":2,"mon":"Mĩ thuật","tuan":34,"tiet":34,"bai":"KIỂM TRA, ĐÁNH GIÁ CUỐI NĂM","yccd":"1. Năng lực mĩ thuật\n- Vận dụng tổng hợp kiến thức, kĩ năng về nét, hình, khối, màu sắc, chân dung, tạo hình con vật đã học cả năm để tạo một sản phẩm mĩ thuật theo chủ đề tự chọn.\n- Trưng bày, giới thiệu và nêu được cảm nhận về sản phẩm của mình.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động hoàn thành sản phẩm đánh giá.\n- Giao tiếp và hợp tác: tự tin giới thiệu sản phẩm trước lớp.\n3. Phẩm chất\n- Chăm chỉ, trung thực trong đánh giá; trân trọng sản phẩm do mình và bạn tạo ra.","dodung":"- Giáo viên: tiêu chí đánh giá cuối năm; bảng trưng bày; thiết bị trình chiếu.\n- Học sinh: đồ dùng mĩ thuật đầy đủ (bút chì, màu, giấy, đất nặn, vật liệu tái sử dụng...).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, nêu mục đích tiết kiểm tra, đánh giá cuối năm.\n- GV giới thiệu tiêu chí đánh giá đơn giản, gần gũi.","hs":"- HS lắng nghe, nắm mục đích và tiêu chí.\n- HS chuẩn bị đồ dùng."},{"ten":"2. Khám phá — Ôn nhanh kiến thức cả năm","gv":"- GV cho HS nhắc lại nhanh các chủ đề đã học trong năm.\n- GV gợi ý HS chọn chủ đề yêu thích để làm sản phẩm.","hs":"- HS nhắc lại các chủ đề đã học.\n- HS chọn chủ đề cho sản phẩm."},{"ten":"3. Luyện tập — Thực hành đánh giá","gv":"- GV yêu cầu HS thực hành tạo một sản phẩm mĩ thuật theo chủ đề tự chọn, vận dụng các kiến thức đã học cả năm.\n- GV quan sát, giúp đỡ khi cần; đánh giá quá trình và sản phẩm của HS.","hs":"- HS thực hành tạo sản phẩm mĩ thuật.\n- HS hoàn thiện sản phẩm để đánh giá."},{"ten":"4. Vận dụng — Trưng bày, đánh giá","gv":"- GV tổ chức cho HS trưng bày, giới thiệu sản phẩm; nêu cảm nhận.\n- GV nhận xét, đánh giá theo hướng động viên, khích lệ; tổng kết năm học.","hs":"- HS trưng bày, giới thiệu sản phẩm.\n- HS nêu cảm nhận, lắng nghe nhận xét."}]},
{"lop":2,"mon":"Mĩ thuật","tuan":35,"tiet":35,"bai":"TRƯNG BÀY SẢN PHẨM CUỐI NĂM","yccd":"1. Năng lực mĩ thuật\n- Lựa chọn, sắp xếp và trưng bày được các sản phẩm mĩ thuật tiêu biểu đã làm trong năm học.\n- Giới thiệu, chia sẻ và nêu cảm nhận về sản phẩm của mình và của bạn.\n- Cảm nhận được vẻ đẹp và sự tiến bộ của bản thân qua các sản phẩm.\n2. Năng lực chung\n- Giao tiếp và hợp tác: phối hợp cùng bạn tổ chức trưng bày, giới thiệu sản phẩm.\n- Giải quyết vấn đề và sáng tạo: sắp xếp không gian trưng bày đẹp mắt.\n3. Phẩm chất\n- Yêu thích môn Mĩ thuật; trân trọng thành quả của mình và của bạn.\n4. Tích hợp\n- Năng lực số 3.2 CB1 (Tích hợp và tinh chỉnh nội dung số): HS chọn được sản phẩm tiêu biểu của mình để đưa vào triển lãm.","dodung":"- Giáo viên: không gian, bảng, giá trưng bày; thiết bị trình chiếu.\n- Học sinh: các sản phẩm mĩ thuật đã làm trong năm học, vật liệu trang trí không gian trưng bày.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV tạo không khí vui tươi, giới thiệu buổi trưng bày sản phẩm cuối năm.\n- GV nêu ý nghĩa của buổi trưng bày.","hs":"- HS hào hứng, lắng nghe.\n- HS chuẩn bị sản phẩm của mình."},{"ten":"2. Khám phá — Chọn và sắp xếp sản phẩm","gv":"- GV hướng dẫn HS lựa chọn các sản phẩm tiêu biểu đã làm trong năm.\n- GV gợi ý cách sắp xếp sản phẩm theo chủ đề, theo nhóm cho đẹp mắt.","hs":"- HS chọn sản phẩm tiêu biểu.\n- HS sắp xếp sản phẩm theo hướng dẫn."},{"ten":"3. Luyện tập — Trưng bày","gv":"- GV tổ chức cho HS trưng bày sản phẩm theo tổ/nhóm, trang trí không gian.\n- GV quan sát, hỗ trợ HS.","hs":"- HS phối hợp trưng bày, trang trí không gian.\n- HS chuẩn bị giới thiệu sản phẩm."},{"ten":"4. Vận dụng — Giới thiệu và chia sẻ","gv":"- GV tổ chức cho HS tham quan, giới thiệu sản phẩm; chia sẻ: Em thích sản phẩm nào nhất? Em tiến bộ ở điều gì?\n- GV nhận xét, tổng kết, động viên cả lớp; khích lệ HS tiếp tục yêu thích mĩ thuật.","hs":"- HS tham quan, giới thiệu và chia sẻ cảm nhận.\n- HS lắng nghe nhận xét, tổng kết."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV cùng HS chọn ảnh sản phẩm ưng ý nhất của mỗi bạn trong cả năm, ghép thành một trang triển lãm cuối năm có ghi tên chủ đề và tên tác giả dưới mỗi ảnh.\n- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 1) HS mời cha mẹ, thầy cô xem trang triển lãm và tập nói lời giới thiệu ngắn về sản phẩm của mình.\n⚠ (Miền 4: An toàn) Trang triển lãm chỉ ghi tên gọi ở lớp của bạn, không ghi họ tên đầy đủ và địa chỉ; chỉ chiếu trong buổi tổng kết ở trường, không đăng lên mạng khi cha mẹ các bạn chưa đồng ý.","hs":"- HS chọn được sản phẩm tiêu biểu của mình để đưa vào triển lãm.\n- HS giới thiệu sản phẩm của mình với người xem một cách tự tin, lễ phép."}]}
];
